insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('d1000000-0000-0000-0000-000000000001', 'mrcp2', 'd469daa0-d080-4b1a-90df-b2dc62ae88d9',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('d1000000-0000-0000-0000-000000000001', 'A', 'Continue amiodarone at a reduced dose and repeat CT in 6 months', false, 'Ruled out because continuing amiodarone in the presence of established pulmonary toxicity risks progression to irreversible fibrosis; the drug should be stopped, not merely reduced.', 1),
('d1000000-0000-0000-0000-000000000001', 'B', 'Start empirical treatment for Pneumocystis jirovecii pneumonia', false, 'Ruled out because there is nothing to suggest immunosuppression or PCP here (no HIV, no other immunosuppressive therapy), and the subacute course with subpleural fibrotic change on CT fits amiodarone toxicity rather than an opportunistic infection.', 2),
('d1000000-0000-0000-0000-000000000001', 'C', 'Arrange bronchoscopy with transbronchial biopsy before any treatment decision', false, 'Ruled out because in a patient with a classic clinical and radiological picture on a known causative drug, biopsy is not required before withdrawing the drug and starting steroids; biopsy is reserved for atypical or diagnostically uncertain cases.', 3),
('d1000000-0000-0000-0000-000000000001', 'D', 'Switch amiodarone to intravenous administration to reduce pulmonary deposition', false, 'Ruled out because the route of administration does not prevent amiodarone pulmonary toxicity, which relates to cumulative dose and tissue accumulation of the drug and its metabolite; the drug needs to be stopped.', 4),
('d1000000-0000-0000-0000-000000000001', 'E', 'Stop amiodarone and start a course of oral corticosteroids', true, 'Correct. The clinical and radiological picture is consistent with amiodarone-induced pulmonary toxicity, a dose- and duration-dependent adverse effect. Management is to withdraw the drug (in consultation with cardiology, considering an alternative antiarrhythmic) and to start corticosteroids in patients with significant symptoms or hypoxia, as this hastens resolution of the inflammatory component.', 5),
('d1000000-0000-0000-0000-000000000002', 'A', 'Reduce the allopurinol dose to 50 mg daily and reassess in one week', false, 'Ruled out because DRESS is a severe, potentially life-threatening hypersensitivity reaction; dose reduction is inadequate and continuing the drug risks fatal multi-organ failure. The drug must be stopped completely and permanently.', 1),
('d1000000-0000-0000-0000-000000000002', 'B', 'Add a xanthine oxidase inhibitor alternative such as febuxostat immediately', false, 'Ruled out because febuxostat can cross-react in allopurinol hypersensitivity and should be avoided in the acute setting; urate-lowering therapy is not the priority during an acute severe drug reaction, and any future choice needs specialist input once the patient recovers.', 2),
('d1000000-0000-0000-0000-000000000002', 'C', 'Stop allopurinol immediately and give supportive care with systemic corticosteroids', true, 'Correct. This presentation (fever, extensive rash, facial oedema, lymphadenopathy, eosinophilia, and multi-organ involvement with hepatic and renal dysfunction) is classic for DRESS syndrome (drug reaction with eosinophilia and systemic symptoms) secondary to allopurinol. Management is immediate withdrawal of the culprit drug plus supportive care, with systemic corticosteroids used for significant organ involvement.', 3),
('d1000000-0000-0000-0000-000000000002', 'D', 'Treat as viral exanthem with antihistamines only and continue allopurinol', false, 'Ruled out because the combination of eosinophilia, hepatic and renal involvement, fever and lymphadenopathy is inconsistent with a simple viral exanthem, and continuing the culprit drug would be dangerous.', 4),
('d1000000-0000-0000-0000-000000000002', 'E', 'Perform patch testing to allopurinol before deciding on further management', false, 'Ruled out because patch testing is not part of acute management of a severe systemic hypersensitivity reaction; the priority is immediate drug withdrawal and supportive/organ-directed treatment, not diagnostic allergy testing at this stage.', 5),
('d1000000-0000-0000-0000-000000000003', 'A', 'Continue methotrexate and add prophylactic co-trimoxazole', false, 'Ruled out because continuing methotrexate in suspected pneumonitis risks rapid clinical deterioration; the drug should be stopped while the diagnosis is clarified, not continued with additional prophylaxis.', 1),
('d1000000-0000-0000-0000-000000000003', 'B', 'Stop methotrexate and start empirical broad-spectrum antibiotics while investigating for methotrexate pneumonitis', true, 'Correct. Subacute dyspnoea, dry cough, fever and bilateral infiltrates in a patient on methotrexate raises strong suspicion of methotrexate-induced pneumonitis, a hypersensitivity-type reaction that is not straightforwardly dose-related. Because infection cannot be excluded on presentation and pneumonitis can be rapidly progressive, the standard approach is to stop methotrexate immediately, treat empirically for infection while awaiting results, and pursue further work-up (HRCT, consideration of bronchoscopy) to support the diagnosis.', 2),
('d1000000-0000-0000-0000-000000000003', 'C', 'Increase the folic acid dose and review in two weeks', false, $x$Ruled out because folic acid supplementation reduces methotrexate's mucocutaneous and gastrointestinal toxicity but does not treat or prevent methotrexate pneumonitis, which is an idiosyncratic hypersensitivity reaction rather than a folate-related toxicity.$x$, 3),
('d1000000-0000-0000-0000-000000000003', 'D', 'Switch immediately to leflunomide without stopping methotrexate first', false, 'Ruled out because starting another disease-modifying drug during an acute, potentially life-threatening pulmonary reaction is inappropriate; the priority is to stop the suspected causative drug and manage the acute presentation, not to substitute DMARDs urgently.', 4),
('d1000000-0000-0000-0000-000000000003', 'E', 'Arrange elective outpatient pulmonary function tests in 4 weeks', false, 'Ruled out because the patient is hypoxic with a progressive presentation and needs urgent inpatient assessment and management now, not deferred outpatient testing.', 5),
('d1000000-0000-0000-0000-000000000004', 'A', 'Stop both simvastatin and clarithromycin, and give aggressive intravenous fluid resuscitation to protect renal function', true, 'Correct. This is statin-induced rhabdomyolysis precipitated by a clinically significant interaction: clarithromycin is a potent CYP3A4 inhibitor that markedly raises simvastatin plasma levels, greatly increasing myopathy/rhabdomyolysis risk. Both drugs should be stopped, and management is supportive with vigorous intravenous fluids to maintain renal perfusion and urine output, protecting against myoglobin-induced acute kidney injury, alongside monitoring of renal function, potassium and CK.', 1),
('d1000000-0000-0000-0000-000000000004', 'B', 'Continue simvastatin but stop clarithromycin, as statins are not usually myotoxic', false, $x$Ruled out because simvastatin is a recognised cause of myopathy and rhabdomyolysis, and in this scenario is very likely the precipitant (via clarithromycin's inhibition of its metabolism); continuing it during rhabdomyolysis with acute kidney injury is inappropriate.$x$, 2),
('d1000000-0000-0000-0000-000000000004', 'C', 'Switch simvastatin to a higher potency statin such as atorvastatin at an equivalent dose', false, 'Ruled out because during acute rhabdomyolysis all statin therapy should be stopped, not switched to another statin; reintroduction of a different statin (if at all) is only considered later once the patient has recovered, often with a lower myopathy-risk agent such as pravastatin.', 3),
('d1000000-0000-0000-0000-000000000004', 'D', 'Start haemodialysis immediately regardless of potassium or acid-base status', false, 'Ruled out because haemodialysis is not routinely indicated for rhabdomyolysis-associated AKI unless there are specific indications (refractory hyperkalaemia, severe acidosis, fluid overload, or established renal failure); the initial priority is aggressive fluid resuscitation.', 4),
('d1000000-0000-0000-0000-000000000004', 'E', 'Reassure the patient that this is a benign statin side effect and continue current medications', false, 'Ruled out because a CK of over 18,000 U/L with rising creatinine represents severe rhabdomyolysis with acute kidney injury, a medical emergency requiring drug cessation and active management, not reassurance and continuation.', 5),
('d1000000-0000-0000-0000-000000000005', 'A', 'Continue hydralazine and start high-dose oral prednisolone for presumed idiopathic SLE', false, 'Ruled out because the strong association with hydralazine, the anti-histone antibody positivity, and the negative anti-dsDNA/normal complement point to drug-induced rather than idiopathic lupus; the key intervention is stopping the causative drug, not treating as idiopathic SLE while continuing it.', 1),
('d1000000-0000-0000-0000-000000000005', 'B', 'Add hydroxychloroquine while continuing hydralazine at the same dose', false, 'Ruled out because continuing the causative agent will perpetuate the syndrome regardless of added immunosuppression; the drug must be withdrawn.', 2),
('d1000000-0000-0000-0000-000000000005', 'C', 'Arrange renal biopsy before making any changes to hydralazine', false, 'Ruled out because renal function is normal and there is no evidence of renal involvement here; biopsy is not indicated, and drug-induced lupus from hydralazine rarely affects the kidneys (unlike idiopathic SLE).', 3),
('d1000000-0000-0000-0000-000000000005', 'D', 'Stop hydralazine and start an alternative antihypertensive agent', true, 'Correct. The clinical picture (polyarthralgia, serositis, constitutional symptoms) with positive ANA and anti-histone antibodies but negative anti-dsDNA and normal complement, in a patient on long-term hydralazine, is classic for drug-induced lupus. Management is to stop the causative drug and substitute an alternative antihypertensive; symptoms typically resolve over weeks to months, and renal and CNS involvement are rare compared with idiopathic SLE.', 4),
('d1000000-0000-0000-0000-000000000005', 'E', 'Test for antiphospholipid antibodies and anticoagulate empirically', false, 'Ruled out because there is no clinical feature here (thrombosis, recurrent miscarriage) suggesting antiphospholipid syndrome; this is not the appropriate next step for this presentation.', 5),
('d1000000-0000-0000-0000-000000000006', 'A', 'Stop lamotrigine immediately and transfer urgently to a specialist burns/dermatology unit for supportive care', true, 'Correct. This presentation is consistent with Stevens-Johnson syndrome/toxic epidermal necrolysis overlap, a life-threatening severe cutaneous adverse reaction strongly associated with lamotrigine, particularly with rapid dose titration. Management requires immediate withdrawal of the culprit drug and urgent transfer to a specialist unit (burns or dermatology) experienced in managing extensive skin loss, with supportive care including fluid and electrolyte management, wound care, analgesia and monitoring for secondary infection.', 1),
('d1000000-0000-0000-0000-000000000006', 'B', 'Continue lamotrigine at the same dose and add a topical corticosteroid', false, 'Ruled out because continuing the causative drug in SJS/TEN risks rapid progression to more extensive skin and mucosal loss with significant mortality risk; the drug must be stopped immediately.', 2),
('d1000000-0000-0000-0000-000000000006', 'C', 'Slow the lamotrigine titration schedule and reassess in one week', false, 'Ruled out because this is an acute, evolving, life-threatening reaction requiring immediate drug cessation and specialist supportive care now, not a gradual dose adjustment.', 3),
('d1000000-0000-0000-0000-000000000006', 'D', 'Start empirical systemic antibiotics for presumed staphylococcal scalded skin syndrome', false, 'Ruled out because the clinical context (recent lamotrigine initiation, target lesions, mucosal involvement) points to a drug-induced severe cutaneous reaction rather than staphylococcal scalded skin syndrome, which is more typical in infants and young children and does not classically involve mucosal surfaces; antibiotics are not the priority intervention.', 4),
('d1000000-0000-0000-0000-000000000006', 'E', 'Perform skin biopsy as an outpatient before deciding on further management', false, 'Ruled out because this is a medical emergency requiring immediate inpatient action (drug withdrawal, specialist unit transfer); biopsy may support the diagnosis but should not delay urgent treatment, and outpatient management is inappropriate given the extent and severity of skin involvement.', 5),
('d1000000-0000-0000-0000-000000000007', 'A', 'Reduce the clozapine dose by half and repeat the full blood count in one month', false, 'Ruled out because significant neutropenia on clozapine mandates immediate cessation of the drug, not dose reduction; continuing any dose risks progression to life-threatening agranulocytosis.', 1),
('d1000000-0000-0000-0000-000000000007', 'B', 'Continue clozapine and start prophylactic broad-spectrum antibiotics', false, 'Ruled out because prophylactic antibiotics do not address the underlying drug-induced neutropenia and do not permit safe continuation of clozapine; the drug must be stopped.', 2),
('d1000000-0000-0000-0000-000000000007', 'C', 'Stop clozapine immediately and refer urgently to haematology, registering the result with the clozapine monitoring service', true, $x$Correct. A neutrophil count of 0.9 x10^9/L represents an 'amber to red' threshold result under UK clozapine monitoring criteria, indicating significant neutropenia with risk of progression to agranulocytosis. Clozapine must be stopped immediately, the result reported to the relevant clozapine patient monitoring service, and urgent haematology referral arranged for further assessment and monitoring of blood count recovery.$x$, 3),
('d1000000-0000-0000-0000-000000000007', 'D', 'Repeat the full blood count in one week before taking any action', false, 'Ruled out because this degree of neutropenia requires immediate action (drug cessation and haematology referral), not a delayed recheck, given the risk of rapid progression to agranulocytosis and life-threatening infection.', 4),
('d1000000-0000-0000-0000-000000000007', 'E', 'Switch immediately to another antipsychotic without stopping clozapine first, cross-titrating over several weeks', false, 'Ruled out because a gradual cross-titration would mean continued clozapine exposure during a period of significant neutropenia; clozapine must be stopped abruptly given the haematological risk, with careful psychiatric management of relapse risk thereafter.', 5),
('d1000000-0000-0000-0000-000000000008', 'A', 'Switch to an angiotensin receptor blocker straight away, as these do not cause angioedema', false, 'Ruled out because although ARB-induced angioedema is less common than with ACE inhibitors, there is a recognised risk of cross-reactivity, particularly in patients who have had ACE inhibitor angioedema; ARBs should be used cautiously or avoided, especially after a severe airway-threatening episode.', 1),
('d1000000-0000-0000-0000-000000000008', 'B', 'Stop the ACE inhibitor permanently and avoid angiotensin receptor blockers due to a recognised (though lower) risk of cross-reactivity', true, 'Correct. This is ACE inhibitor-induced angioedema, a bradykinin-mediated (non-allergic, non-histaminergic) reaction that can occur even after years of uneventful use. The ACE inhibitor must be stopped permanently. Because angioedema with ARBs occurs in a small proportion (roughly 2-10%) of patients with prior ACE inhibitor angioedema, ARBs are generally used with caution or avoided in favour of an alternative drug class such as a calcium channel blocker, particularly after a severe reaction.', 2),
('d1000000-0000-0000-0000-000000000008', 'C', 'Continue the ACE inhibitor but add regular antihistamines for symptom control', false, 'Ruled out because ACE inhibitor angioedema is bradykinin-mediated, not histamine-mediated, so antihistamines are ineffective; continuing the drug risks recurrent, potentially fatal airway obstruction.', 3),
('d1000000-0000-0000-0000-000000000008', 'D', 'Reduce the ACE inhibitor dose by half and monitor for recurrence', false, 'Ruled out because angioedema is not reliably dose-related and can recur unpredictably; the drug must be stopped completely, not merely reduced.', 4),
('d1000000-0000-0000-0000-000000000008', 'E', 'Continue the ACE inhibitor as this episode is unrelated given 6 years of prior tolerance', false, 'Ruled out because ACE inhibitor angioedema can occur at any point during treatment, including after years of uneventful use, and this presentation (acute lip/tongue swelling with stridor, no urticaria) is classic; the temporal relationship with a specific trigger is not required as it is with allergic reactions.', 5),
('d1000000-0000-0000-0000-000000000009', 'A', 'Give idarucizumab as the specific reversal agent', false, 'Ruled out because idarucizumab is the specific reversal agent for dabigatran (a direct thrombin inhibitor), not for factor Xa inhibitors such as apixaban; it would have no reversal effect here.', 1),
('d1000000-0000-0000-0000-000000000009', 'B', 'Give intravenous vitamin K and fresh frozen plasma', false, 'Ruled out because vitamin K and FFP reverse vitamin K antagonists (warfarin) by replenishing vitamin K-dependent clotting factors; they are not effective reversal strategies for direct oral anticoagulants such as apixaban.', 2),
('d1000000-0000-0000-0000-000000000009', 'C', 'Withhold apixaban and await its natural clearance without pharmacological reversal', false, 'Ruled out because the patient has life-threatening major bleeding with haemodynamic instability; active reversal is indicated rather than simply waiting for drug clearance, particularly as apixaban has a half-life of 8-15 hours which would delay haemostasis unacceptably in this context.', 3),
('d1000000-0000-0000-0000-000000000009', 'D', 'Give andexanet alfa, or if unavailable, four-factor prothrombin complex concentrate', true, 'Correct. This is life-threatening major bleeding on a factor Xa inhibitor (apixaban). Andexanet alfa is the specific reversal agent for factor Xa inhibitors and is indicated for life-threatening bleeding; where it is unavailable, four-factor prothrombin complex concentrate (PCC) is used as an alternative, non-specific haemostatic agent, alongside standard resuscitation, endoscopy and correction of anaemia.', 4),
('d1000000-0000-0000-0000-000000000009', 'E', 'Give protamine sulfate to reverse the anticoagulant effect', false, 'Ruled out because protamine sulfate reverses unfractionated heparin (and partially reverses low molecular weight heparin); it has no effect on factor Xa inhibitors like apixaban.', 5),
('d1000000-0000-0000-0000-000000000010', 'A', 'Continue triple therapy with aspirin, clopidogrel and apixaban for the full 12 months', false, 'Ruled out because prolonged triple therapy substantially increases major bleeding risk without proportionate ischaemic benefit compared with early aspirin discontinuation; guidelines recommend limiting triple therapy duration.', 1),
('d1000000-0000-0000-0000-000000000010', 'B', 'Stop apixaban and continue dual antiplatelet therapy with aspirin and clopidogrel alone', false, 'Ruled out because this patient has a clear indication for long-term anticoagulation (AF with CHA2DS2-VASc 4); stopping the anticoagulant in favour of antiplatelets alone would leave him inadequately protected against cardioembolic stroke.', 2),
('d1000000-0000-0000-0000-000000000010', 'C', 'Stop clopidogrel and continue aspirin plus apixaban as dual therapy', false, 'Ruled out because after PCI with stenting, a P2Y12 inhibitor (not aspirin) is the preferred antiplatelet to combine with the anticoagulant during the dual therapy phase, reflecting stent-related ischaemic risk; guideline-directed dual therapy is P2Y12 inhibitor plus anticoagulant, with aspirin stopped early.', 3),
('d1000000-0000-0000-0000-000000000010', 'D', 'Switch apixaban to warfarin to allow easier monitoring during the combination therapy period', false, 'Ruled out because there is no indication to switch to warfarin here; DOACs are preferred over warfarin in combination antithrombotic regimens post-PCI in AF because they are associated with lower bleeding risk in this setting, provided renal function and adherence are adequate.', 4),
('d1000000-0000-0000-0000-000000000010', 'E', 'Stop aspirin after discharge (or within the first week), continuing clopidogrel plus apixaban for up to 12 months, then apixaban alone', true, 'Correct. Current guidance for patients with AF requiring anticoagulation who undergo PCI favours minimising triple therapy duration because of high bleeding risk. Standard practice is a short period of triple therapy (often just peri-procedurally, or omitted altogether in lower-risk patients) followed by dual therapy with a P2Y12 inhibitor (usually clopidogrel) plus a DOAC for up to 12 months, after which anticoagulant monotherapy continues long-term for stroke prevention.', 5),
('d1000000-0000-0000-0000-000000000011', 'A', 'Withhold warfarin and give oral vitamin K, with INR rechecked the following day', true, 'Correct. For a markedly supratherapeutic INR (>8) with minor bleeding that has settled, guidance recommends withholding warfarin and giving vitamin K (oral, typically low dose) to correct the INR more rapidly than withholding alone, with the INR rechecked within 24 hours and warfarin restarted at a lower dose once INR falls below the therapeutic range.', 1),
('d1000000-0000-0000-0000-000000000011', 'B', 'Continue warfarin at the same dose and monitor INR weekly', false, 'Ruled out because an INR of 8.9 carries a significant risk of major bleeding (particularly given the mechanical valve and hence lifelong warfarin need); continuing at the same dose without intervention is inappropriate.', 2),
('d1000000-0000-0000-0000-000000000011', 'C', 'Give intravenous vitamin K and four-factor prothrombin complex concentrate immediately', false, 'Ruled out because this combination (rapid full reversal with PCC) is reserved for major, life-threatening bleeding; this patient has only minor, now-settled bleeding, so vitamin K alone (without PCC) with temporary cessation of warfarin is the appropriate, more measured approach, especially given the need to avoid over-reversal in a mechanical valve patient at high thrombotic risk.', 3),
('d1000000-0000-0000-0000-000000000011', 'D', 'Stop warfarin permanently and switch to a direct oral anticoagulant', false, 'Ruled out because DOACs are contraindicated in patients with mechanical heart valves due to increased risk of valve thrombosis and stroke demonstrated in trials; warfarin remains the anticoagulant of choice in this context and should be restarted once the INR is controlled.', 4),
('d1000000-0000-0000-0000-000000000011', 'E', 'Omit vitamin K and simply withhold one dose of warfarin before resuming at the same dose', false, 'Ruled out because at this level of INR elevation (>8), vitamin K administration is recommended in addition to withholding warfarin, to reduce bleeding risk more effectively than dose omission alone; simply resuming the same dose without adjustment also risks recurrent over-anticoagulation.', 5),
('d1000000-0000-0000-0000-000000000012', 'A', 'Switch from unfractionated heparin to a low molecular weight heparin', false, 'Ruled out because LMWH cross-reacts with HIT antibodies and is contraindicated once HIT is suspected; all heparin products must be avoided, not substituted for another heparin formulation.', 1),
('d1000000-0000-0000-0000-000000000012', 'B', 'Stop heparin and start warfarin immediately as monotherapy', false, 'Ruled out because starting warfarin alone (without an alternative parenteral anticoagulant first) in acute HIT risks warfarin-induced skin necrosis and venous limb gangrene due to a transient hypercoagulable state from rapid protein C depletion; warfarin should only be introduced once platelets have substantially recovered (typically >150) and should overlap with a non-heparin parenteral anticoagulant.', 2),
('d1000000-0000-0000-0000-000000000012', 'C', 'Give a platelet transfusion to correct the thrombocytopenia before further management', false, 'Ruled out because platelet transfusion in HIT does not address the underlying antibody-mediated process and can theoretically fuel further thrombosis; it is reserved for significant bleeding or before invasive procedures, not used routinely to correct the platelet count in HIT.', 3),
('d1000000-0000-0000-0000-000000000012', 'D', 'Continue unfractionated heparin at a reduced dose and monitor platelet count daily', false, 'Ruled out because continuing heparin in suspected HIT, at any dose, perpetuates the prothrombotic antibody-mediated process and risks further thrombosis, including limb-threatening or life-threatening events; heparin must be stopped entirely.', 4),
('d1000000-0000-0000-0000-000000000012', 'E', 'Stop all heparin products immediately and start a non-heparin anticoagulant such as argatroban or fondaparinux', true, 'Correct. The clinical picture (thrombocytopenia with a temporal relationship to heparin exposure, new thrombosis despite anticoagulation, high 4T score) is strongly suggestive of heparin-induced thrombocytopenia (HIT), a prothrombotic, antibody-mediated disorder. Management does not wait for confirmatory testing: all heparin (including LMWH and heparin-coated devices) must be stopped immediately, and a non-heparin anticoagulant (e.g. argatroban, a direct thrombin inhibitor, or fondaparinux) started to treat the ongoing thrombotic risk.', 5),
('d1000000-0000-0000-0000-000000000013', 'A', 'Stop all anticoagulation until the second trimester to avoid fetal harm', false, 'Ruled out because stopping anticoagulation entirely in a patient with a mechanical valve carries an unacceptably high risk of valve thrombosis, stroke and death; anticoagulation must be continued throughout pregnancy in some form.', 1),
('d1000000-0000-0000-0000-000000000013', 'B', 'Continue warfarin at the current dose unchanged throughout the entire pregnancy including delivery', false, 'Ruled out because warfarin is teratogenic in the first trimester (warfarin embryopathy) and also crosses the placenta near term, risking fetal intracranial haemorrhage during delivery; standard practice is to switch to heparin before delivery, and to consider heparin or dose-based decisions in the first trimester as above.', 2),
('d1000000-0000-0000-0000-000000000013', 'C', 'Switch to a direct oral anticoagulant such as apixaban for the duration of pregnancy', false, 'Ruled out because DOACs are contraindicated both in mechanical heart valves (increased thrombotic risk demonstrated in trials) and in pregnancy (inadequate safety data, and known placental transfer); this is not an appropriate option in either respect.', 3),
('d1000000-0000-0000-0000-000000000013', 'D', 'Switch to dose-adjusted therapeutic low molecular weight heparin (with anti-Xa monitoring) or continue warfarin if the dose requirement is low, after detailed discussion of risks and benefits', true, $x$Correct. Warfarin crosses the placenta and is associated with a dose-dependent risk of warfarin embryopathy, particularly with exposure between 6 and 12 weeks' gestation, but it provides the most effective protection against valve thrombosis. Current guidance (e.g. ESC) recommends an individualised discussion: for women needing a low warfarin dose (e.g. <5 mg/day), continuing warfarin with close monitoring may be reasonable, while others switch to dose-adjusted LMWH with anti-Xa level monitoring (or unfractionated heparin) during the first trimester to avoid embryopathy, accepting a potentially higher (though still guideline-supported when properly monitored) thrombotic risk than warfarin.$x$, 4),
('d1000000-0000-0000-0000-000000000013', 'E', 'Use prophylactic-dose (rather than therapeutic-dose) low molecular weight heparin, as this provides adequate valve protection', false, 'Ruled out because prophylactic-dose LMWH is inadequate to prevent valve thrombosis in a patient with a mechanical valve; therapeutic, weight-adjusted dosing with anti-Xa monitoring is required if heparin is used.', 5),
('d1000000-0000-0000-0000-000000000014', 'A', 'Bridge with therapeutic-dose low molecular weight heparin throughout the perioperative period', false, 'Ruled out because bridging anticoagulation in this lower-risk AF population increases bleeding complications without a proven reduction in thromboembolic events, and is not recommended by current guidelines for patients at this risk level.', 1),
('d1000000-0000-0000-0000-000000000014', 'B', 'Continue warfarin unchanged through the perioperative period, as this is only a low-risk procedure', false, $x$Ruled out because continuing warfarin unchanged is not accepted practice around most surgical procedures given bleeding risk, even 'low bleeding risk' ones; the standard approach is short interruption without bridging for this risk profile.$x$, 2),
('d1000000-0000-0000-0000-000000000014', 'C', 'Stop warfarin 5 days before surgery without bridging anticoagulation, and restart postoperatively once haemostasis is secure', true, 'Correct. In patients with AF at low-to-moderate thromboembolic risk (no mechanical valve, no recent stroke/TIA, moderate CHA2DS2-VASc) undergoing surgery, bridging with heparin is not recommended, as trial evidence (e.g. BRIDGE) shows bridging increases bleeding without reducing thromboembolic events in this population. Warfarin is simply stopped several days beforehand to allow the INR to normalise, and restarted after surgery once bleeding risk has settled.', 3),
('d1000000-0000-0000-0000-000000000014', 'D', 'Cancel the procedure until a mechanical valve can be excluded by echocardiography', false, 'Ruled out because there is no clinical indication here (no murmur, no history) to suspect a mechanical valve; this is unnecessary and would inappropriately delay a routine elective procedure.', 4),
('d1000000-0000-0000-0000-000000000014', 'E', 'Switch to a direct oral anticoagulant for the perioperative period to simplify management', false, 'Ruled out because switching anticoagulant class purely for perioperative convenience is not standard practice and introduces unnecessary complexity/risk; the established approach is simply to interrupt warfarin without bridging in this risk category.', 5),
('d1000000-0000-0000-0000-000000000015', 'A', 'Apixaban is contraindicated at any dose because her eGFR is below 30 mL/min/1.73m2', false, 'Ruled out because apixaban is not contraindicated until eGFR falls below approximately 15 mL/min/1.73m2 (or the patient is on dialysis, where evidence and licensing vary); at an eGFR of 28, apixaban can still be used, with dose reduction based on the specific criteria met.', 1),
('d1000000-0000-0000-0000-000000000015', 'B', 'Apixaban 2.5 mg twice daily is appropriate, as she meets two of the three dose-reduction criteria (age >=80, weight <=60 kg, creatinine >=133 micromol/L)', true, 'Correct. Apixaban dose reduction to 2.5 mg twice daily applies when a patient meets at least two of three criteria: age >=80 years, body weight <=60 kg, or serum creatinine >=133 micromol/L. This patient meets the weight and creatinine criteria (58 kg and 148 micromol/L), so the reduced dose is appropriate; apixaban can still be used down to an eGFR of around 15 mL/min/1.73m2, unlike some other DOACs which are more restricted in significant renal impairment.', 2),
('d1000000-0000-0000-0000-000000000015', 'C', 'Standard-dose apixaban 5 mg twice daily should be used, as renal impairment alone does not warrant dose reduction', false, 'Ruled out because this patient meets two of the three specific dose-reduction criteria (low body weight and elevated creatinine), which mandates the reduced 2.5 mg twice daily dose regardless of eGFR category per se; using the standard dose would risk drug accumulation and bleeding.', 3),
('d1000000-0000-0000-0000-000000000015', 'D', 'Switch to dabigatran, which is preferred over apixaban in this degree of renal impairment', false, 'Ruled out because dabigatran is predominantly renally excreted (around 80%) and is generally avoided or requires greater caution at lower eGFRs compared with apixaban, which has the least renal dependence among the DOACs; apixaban is often the preferred DOAC choice in renal impairment, not dabigatran.', 4),
('d1000000-0000-0000-0000-000000000015', 'E', 'Switch to warfarin, as no DOAC can be used with this degree of renal impairment', false, 'Ruled out because apixaban remains appropriate (with dose adjustment) at this level of renal function; switching to warfarin is not required, although warfarin remains an option if DOACs become contraindicated at more severe renal impairment (eGFR <15) or on dialysis.', 5),
('d1000000-0000-0000-0000-000000000016', 'A', 'Stop all antiplatelet therapy indefinitely given the severity of the bleed', false, 'Ruled out because this patient remains at significant risk of stent thrombosis and recurrent ischaemic events following recent ACS/PCI; stopping all antiplatelet therapy is not appropriate and risks a potentially fatal thrombotic stent occlusion.', 1),
('d1000000-0000-0000-0000-000000000016', 'B', 'Continue ticagrelor and aspirin unchanged, as GI bleeding is unrelated to antiplatelet potency', false, 'Ruled out because ticagrelor is associated with higher bleeding risk than clopidogrel, and continuing the same regimen after a major bleed without any modification or gastroprotection is inappropriate given the demonstrated bleeding risk in this patient.', 2),
('d1000000-0000-0000-0000-000000000016', 'C', 'Switch to aspirin monotherapy, stopping the P2Y12 inhibitor completely', false, 'Ruled out because stopping dual antiplatelet therapy entirely this soon after stenting (3 months) still carries meaningful stent thrombosis risk in many patients, particularly in the context of ACS; de-escalation of potency (to clopidogrel) while maintaining dual therapy, with gastroprotection, is generally preferred over dropping to monotherapy this early unless bleeding risk is judged to markedly outweigh ischaemic risk.', 3),
('d1000000-0000-0000-0000-000000000016', 'D', 'Add a proton pump inhibitor and continue the same aspirin/ticagrelor regimen unchanged', false, 'Ruled out because while a PPI is appropriate, continuing full-potency ticagrelor without de-escalation does not adequately address the demonstrated excess bleeding risk in this patient; a combined strategy of de-escalation plus gastroprotection is preferred.', 4),
('d1000000-0000-0000-0000-000000000016', 'E', 'De-escalate from ticagrelor to clopidogrel while continuing dual antiplatelet therapy with aspirin, alongside a proton pump inhibitor', true, 'Correct. In patients with high bleeding risk who have completed the highest-risk early post-PCI period, guideline-supported de-escalation strategies include switching from a potent P2Y12 inhibitor (ticagrelor or prasugrel) to clopidogrel, which has a lower bleeding risk profile, while maintaining dual antiplatelet therapy for its ongoing protective effect against stent thrombosis, combined with a PPI for gastric mucosal protection given the recent GI bleed.', 5),
('d1000000-0000-0000-0000-000000000017', 'A', 'Trimethoprim induces hepatic warfarin metabolism, and no action is needed as INR will normalise spontaneously within 24 hours', false, 'Ruled out because trimethoprim inhibits (not induces) warfarin metabolism, and an INR of 6.8 with bleeding requires active intervention (vitamin K), not simply awaiting spontaneous normalisation, which would take days rather than hours.', 1),
('d1000000-0000-0000-0000-000000000017', 'B', 'Trimethoprim displaces warfarin from plasma protein binding sites, and the interaction is clinically insignificant', false, 'Ruled out because although some interactions involve protein-binding displacement, the clinically important mechanism here is CYP2C9 enzyme inhibition, and the interaction is clearly clinically significant given the marked INR rise and bleeding.', 2),
('d1000000-0000-0000-0000-000000000017', 'C', 'This represents warfarin resistance and the dose should be increased', false, 'Ruled out because the clinical and biochemical picture (raised INR, bleeding) indicates enhanced, not reduced, anticoagulant effect; increasing the dose would be dangerous.', 3),
('d1000000-0000-0000-0000-000000000017', 'D', 'Trimethoprim inhibits CYP2C9-mediated warfarin metabolism, raising INR; withhold warfarin and give oral vitamin K given the INR level with minor bleeding', true, 'Correct. Trimethoprim (and co-trimoxazole) inhibits CYP2C9, the principal enzyme responsible for metabolising the more potent S-warfarin enantiomer, leading to reduced clearance, raised warfarin levels and an elevated INR. With an INR of 6.8 and minor bleeding, guidance recommends withholding warfarin and giving oral vitamin K, with INR rechecked and warfarin restarted at a lower dose once corrected.', 4),
('d1000000-0000-0000-0000-000000000017', 'E', 'Trimethoprim has no recognised interaction with warfarin, and an alternative cause for the bleeding should be sought', false, $x$Ruled out because trimethoprim is a well-recognised, clinically important CYP2C9 inhibitor that significantly potentiates warfarin's effect; this is the most likely explanation given the clear temporal relationship.$x$, 5),
('d1000000-0000-0000-0000-000000000018', 'A', 'Continue atorvastatin at the same dose, as the interaction with macrolides is not clinically significant', false, 'Ruled out because the clarithromycin-atorvastatin interaction is well-documented and clinically significant, evidenced here by a markedly raised CK; continuing at the same dose risks progression to rhabdomyolysis.', 1),
('d1000000-0000-0000-0000-000000000018', 'B', 'Switch clarithromycin to azithromycin, which has a similarly significant CYP3A4 interaction with statins', false, 'Ruled out because although azithromycin is sometimes preferred over clarithromycin/erythromycin due to a lower propensity for CYP3A4 interaction, at this point the patient already has evidence of early rhabdomyolysis (raised CK); the statin itself should be withheld now regardless of which macrolide is used, and azithromycin does still carry some interaction potential.', 2),
('d1000000-0000-0000-0000-000000000018', 'C', 'Withhold atorvastatin for the duration of clarithromycin treatment and monitor CK and renal function', true, 'Correct. Clarithromycin is a potent CYP3A4 inhibitor and atorvastatin is metabolised via CYP3A4; co-administration significantly raises atorvastatin levels and myopathy/rhabdomyolysis risk, as demonstrated by the raised CK here. Statin therapy should be temporarily withheld for the duration of the interacting antibiotic course, with monitoring of CK and renal function, and restarted once the antibiotic course is complete and symptoms/CK have resolved.', 3),
('d1000000-0000-0000-0000-000000000018', 'D', 'Increase the atorvastatin dose to compensate for reduced hepatic clearance', false, 'Ruled out because increasing the dose in the context of impaired clearance (due to CYP3A4 inhibition) would further raise levels and worsen myopathy risk; the correct action is to withhold, not increase, the statin.', 4),
('d1000000-0000-0000-0000-000000000018', 'E', 'Switch to a higher-intensity statin such as rosuvastatin without addressing the interacting antibiotic', false, 'Ruled out because rosuvastatin is less dependent on CYP3A4 metabolism but caution is still needed in this acute myopathic presentation; the priority is to stop statin therapy now given the established CK rise, not swap to another statin while continuing clarithromycin.', 5),
('d1000000-0000-0000-0000-000000000019', 'A', 'Stop linezolid and sertraline, and provide supportive care including cooling, benzodiazepines and consideration of cyproheptadine if severe', true, 'Correct. Linezolid has weak, reversible monoamine oxidase inhibitor activity, and its combination with an SSRI (sertraline) has precipitated serotonin syndrome (agitation, autonomic instability, hyperreflexia, clonus, hyperthermia). Management is to stop all serotonergic agents, provide supportive care (cooling, IV fluids, benzodiazepines for agitation and to reduce muscle rigidity/hyperthermia), and consider the serotonin antagonist cyproheptadine in more severe or refractory cases.', 1),
('d1000000-0000-0000-0000-000000000019', 'B', 'Continue both drugs but add regular paracetamol for the fever', false, 'Ruled out because continuing both serotonergic agents will worsen serotonin syndrome, which can progress to life-threatening hyperthermia, seizures and cardiovascular instability; both must be stopped.', 2),
('d1000000-0000-0000-0000-000000000019', 'C', 'Stop sertraline only and continue linezolid to complete the antibiotic course', false, 'Ruled out because linezolid itself has MAOI activity contributing to the serotonin syndrome; both the antibiotic and the SSRI should be stopped, and if antimicrobial therapy is still required an alternative agent without serotonergic/MAOI activity should be used.', 3),
('d1000000-0000-0000-0000-000000000019', 'D', 'Give an antipsychotic such as haloperidol as first-line treatment', false, 'Ruled out because antipsychotics are not first-line for serotonin syndrome and can complicate the picture (e.g. anticholinergic effects, QT prolongation); benzodiazepines and supportive care with cyproheptadine (if needed) are preferred.', 4),
('d1000000-0000-0000-0000-000000000019', 'E', 'Reassure the patient that this is a known but self-limiting reaction requiring no specific intervention', false, 'Ruled out because serotonin syndrome can be severe and life-threatening (hyperthermia, rhabdomyolysis, seizures, cardiovascular collapse); active management is required, not simple reassurance.', 5),
('d1000000-0000-0000-0000-000000000020', 'A', 'This is an unrelated presentation of RA flare with vasculitic rash; continue both drugs and treat the flare with increased corticosteroids', false, 'Ruled out because pancytopenia with mucositis in this context is a recognised and dangerous interaction between methotrexate and co-trimoxazole, not an RA flare; continuing both drugs would be dangerous.', 1),
('d1000000-0000-0000-0000-000000000020', 'B', 'Co-trimoxazole has potentiated methotrexate toxicity via synergistic folate antagonism and reduced renal clearance; stop both drugs and give folinic acid (calcium folinate) rescue with supportive care', true, $x$Correct. Trimethoprim-sulfamethoxazole is itself a folate antagonist and also reduces renal tubular clearance of methotrexate, and the combination is a well-recognised cause of severe, sometimes fatal, pancytopenia and mucositis. Both drugs must be stopped immediately, folinic acid (folinic acid/calcium folinate) rescue given to counteract methotrexate's antifolate effect, and supportive care provided (transfusion support, infection precautions, monitoring for sepsis given neutropenia).$x$, 2),
('d1000000-0000-0000-0000-000000000020', 'C', 'Give folic acid alone at the usual weekly supplementation dose and continue both drugs', false, 'Ruled out because standard low-dose folic acid supplementation is inadequate to reverse established severe methotrexate toxicity; folinic acid (leucovorin) rescue at treatment doses is required, and both causative drugs must be stopped.', 3),
('d1000000-0000-0000-0000-000000000020', 'D', 'Stop co-trimoxazole only, and continue methotrexate at a reduced dose', false, 'Ruled out because with established pancytopenia and mucositis (methotrexate toxicity), methotrexate itself must also be stopped and folinic acid rescue given; continuing it at a reduced dose is unsafe in this acute toxic state.', 4),
('d1000000-0000-0000-0000-000000000020', 'E', 'Arrange bone marrow biopsy before starting any treatment', false, 'Ruled out because this is a medical emergency requiring immediate cessation of both causative drugs and urgent folinic acid rescue plus supportive care; bone marrow biopsy is not required to make this diagnosis and would inappropriately delay life-saving treatment.', 5),
('d1000000-0000-0000-0000-000000000021', 'A', 'This represents a normal, expected consequence of heart failure progression unrelated to the ibuprofen', false, 'Ruled out because the clear temporal relationship with NSAID initiation, combined with the known pharmacological interaction with ACE inhibitors and spironolactone, strongly implicates the NSAID; this is not simply disease progression.', 1),
('d1000000-0000-0000-0000-000000000021', 'B', 'NSAID-induced reduction in renal prostaglandin-mediated perfusion has precipitated acute kidney injury, compounding hyperkalaemia from combined ACE inhibitor and spironolactone therapy', true, $x$Correct. This is a classic 'triple whammy'-type interaction: ACE inhibitors and potassium-sparing diuretics (spironolactone) both promote potassium retention, and NSAIDs reduce renal prostaglandin synthesis, impairing renal perfusion (particularly in a patient already reliant on prostaglandin-mediated afferent arteriolar dilation) and precipitating acute kidney injury, which further impairs potassium excretion. The combination has caused severe, dangerous hyperkalaemia and AKI.$x$, 2),
('d1000000-0000-0000-0000-000000000021', 'C', 'Bisoprolol toxicity is the most likely cause of the renal impairment and hyperkalaemia', false, 'Ruled out because beta-blockers are not typically associated with acute kidney injury or hyperkalaemia of this severity in this way; the ACE inhibitor/spironolactone/NSAID interaction is the recognised mechanism here.', 3),
('d1000000-0000-0000-0000-000000000021', 'D', 'Spironolactone alone at this dose is inappropriate and should never be combined with an ACE inhibitor', false, 'Ruled out because spironolactone combined with an ACE inhibitor and beta-blocker is standard, guideline-recommended triple therapy for HFrEF with regular potassium/renal function monitoring; the acute deterioration here is precipitated by the added NSAID, not an inherent incompatibility of the heart failure regimen itself.', 4),
('d1000000-0000-0000-0000-000000000021', 'E', $x$This is unrelated to medication and represents primary Addison's disease presenting acutely$x$, false, 'Ruled out because the clear temporal association with NSAID initiation in a patient on an ACE inhibitor and spironolactone provides a much more likely explanation than new-onset adrenal insufficiency, which would not typically present with this acute pattern in this context.', 5),
('d1000000-0000-0000-0000-000000000022', 'A', 'Continue both drugs, as phenytoin toxicity is not associated with azole antifungals', false, 'Ruled out because azole antifungals (particularly fluconazole and, more potently, itraconazole/voriconazole) are well-recognised inhibitors of phenytoin metabolism, and continuing both drugs would risk worsening toxicity, including ataxia-related falls and, at very high levels, seizures or cardiovascular effects.', 1),
('d1000000-0000-0000-0000-000000000022', 'B', 'Increase the phenytoin dose to overcome reduced efficacy from enzyme induction', false, 'Ruled out because fluconazole inhibits (not induces) phenytoin metabolism, and the clinical and biochemical picture shows toxicity (elevated level), not reduced efficacy; increasing the dose would be dangerous.', 2),
('d1000000-0000-0000-0000-000000000022', 'C', 'Switch phenytoin to an equivalent dose of a different antiepileptic without any monitoring', false, 'Ruled out because abrupt drug switches without appropriate cross-titration and monitoring risk both breakthrough seizures and ongoing toxicity; the priority is addressing the current toxicity (stopping the interacting drug, withholding/adjusting phenytoin) rather than an unmonitored switch.', 3),
('d1000000-0000-0000-0000-000000000022', 'D', 'Stop fluconazole, withhold phenytoin temporarily, and recheck phenytoin levels before resuming at an adjusted dose', true, $x$Correct. Fluconazole is a significant inhibitor of CYP2C9 and CYP2C19, the enzymes responsible for phenytoin metabolism, and has precipitated phenytoin toxicity (nystagmus, ataxia, dysarthria, drowsiness are the classic features of a supratherapeutic level). Management is to stop the interacting drug, temporarily withhold phenytoin, and recheck levels (given phenytoin's non-linear, zero-order kinetics at higher concentrations, levels may fall unpredictably slowly) before cautiously resuming at an appropriate, likely lower, maintenance dose.$x$, 4),
('d1000000-0000-0000-0000-000000000022', 'E', 'Give activated charcoal, as this is equivalent to an acute overdose situation', false, 'Ruled out because this is a chronic drug interaction causing gradually accumulating toxicity via reduced metabolism, not an acute oral overdose; activated charcoal has no role here.', 5),
('d1000000-0000-0000-0000-000000000023', 'A', 'Continue both digoxin and amiodarone at the same doses, as this interaction is not clinically significant', false, 'Ruled out because the amiodarone-digoxin interaction is well-established and clinically significant, commonly requiring an empirical digoxin dose reduction (often by around 30-50%) when amiodarone is started, and here has already caused clear toxicity requiring active management.', 1),
('d1000000-0000-0000-0000-000000000023', 'B', $x$Increase the digoxin dose to compensate for amiodarone's antiarrhythmic effect$x$, false, 'Ruled out because the presentation indicates digoxin toxicity (elevated level, toxic symptoms), not reduced efficacy; increasing the dose would be dangerous and could precipitate life-threatening arrhythmia.', 2),
('d1000000-0000-0000-0000-000000000023', 'C', 'Give intravenous calcium gluconate as first-line treatment for the ventricular ectopy', false, $x$Ruled out because intravenous calcium is contraindicated in digoxin toxicity, as it can worsen cardiac toxicity by further raising intracellular calcium in already digoxin-toxic myocytes (a risk sometimes summarised as 'stone heart'); management should follow the standard digoxin toxicity pathway.$x$, 3),
('d1000000-0000-0000-0000-000000000023', 'D', 'Perform haemodialysis to remove digoxin from the circulation', false, 'Ruled out because digoxin has a very large volume of distribution and is not effectively removed by haemodialysis; digoxin-specific antibody fragments, not dialysis, are the definitive treatment for significant digoxin toxicity.', 4),
('d1000000-0000-0000-0000-000000000023', 'E', 'Stop digoxin, correct any electrolyte abnormalities, and consider digoxin-specific antibody fragments (DigiFab) if there is haemodynamic compromise or significant arrhythmia', true, 'Correct. Amiodarone inhibits P-glycoprotein-mediated renal and biliary excretion of digoxin (and displaces it from tissue binding sites), commonly raising digoxin levels significantly and precipitating toxicity, as seen here (GI symptoms, visual disturbance, ventricular ectopy). Management is to stop digoxin, correct contributing electrolyte disturbances (particularly hypokalaemia, which potentiates digoxin toxicity), and give digoxin-specific antibody fragments if there is significant arrhythmia or haemodynamic compromise.', 5),
('d1000000-0000-0000-0000-000000000024', 'A', 'Switch omeprazole to pantoprazole, which has less CYP2C19 inhibitory activity, while continuing clopidogrel', true, $x$Correct. Clopidogrel is a prodrug requiring CYP2C19-mediated activation to its active metabolite, and omeprazole (and esomeprazole) is a relatively potent CYP2C19 inhibitor, theoretically reducing clopidogrel's antiplatelet effect. While the clinical significance of this interaction remains debated, current practice favours using a PPI with less CYP2C19 inhibition (such as pantoprazole or lansoprazole) in patients who require both gastroprotection and clopidogrel, rather than omitting gastroprotection or omitting clopidogrel.$x$, 1),
('d1000000-0000-0000-0000-000000000024', 'B', 'Stop clopidogrel and continue omeprazole, as gastroprotection takes priority', false, 'Ruled out because stopping the P2Y12 inhibitor only 2 months after ACS/PCI with a drug-eluting stent risks stent thrombosis; gastroprotection should be adjusted (PPI choice), not achieved by discontinuing essential antiplatelet therapy.', 2),
('d1000000-0000-0000-0000-000000000024', 'C', 'Continue omeprazole and clopidogrel together, as PPIs should always be avoided with dual antiplatelet therapy regardless of type', false, 'Ruled out because PPIs are often indicated for gastroprotection in patients on dual antiplatelet therapy (particularly with risk factors for GI bleeding); the issue is the specific choice of PPI, not blanket avoidance, and stopping gastroprotection would increase GI bleeding risk unnecessarily.', 3),
('d1000000-0000-0000-0000-000000000024', 'D', 'Switch clopidogrel to aspirin monotherapy, discontinuing dual antiplatelet therapy entirely', false, 'Ruled out because dual antiplatelet therapy is indicated for a defined period following ACS/PCI with stenting to reduce stent thrombosis risk; this should not be abandoned because of a PPI choice issue, which can be addressed by selecting a different PPI.', 4),
('d1000000-0000-0000-0000-000000000024', 'E', 'Double the clopidogrel dose to overcome any reduction in antiplatelet effect from omeprazole', false, 'Ruled out because empirically doubling the dose is not standard practice for managing this interaction; the preferred approach is choosing a PPI with lower interaction potential, with platelet function testing reserved for selected higher-risk scenarios rather than routine dose escalation.', 5),
('d1000000-0000-0000-0000-000000000025', 'A', $x$A loading dose works by increasing the drug's clearance, allowing steady state to be reached sooner$x$, false, 'Ruled out because a loading dose does not alter clearance; it achieves a target concentration immediately by providing enough drug to fill the volume of distribution, while maintenance dosing (governed by clearance and half-life) then sustains that concentration.', 1),
('d1000000-0000-0000-0000-000000000025', 'B', 'A loading dose bypasses first-pass metabolism, unlike maintenance dosing', false, 'Ruled out because loading and maintenance doses of the same drug via the same route undergo the same first-pass metabolism (if given orally); the loading dose concept relates to volume of distribution, not bioavailability or first-pass effect.', 2),
('d1000000-0000-0000-0000-000000000025', 'C', 'A loading dose achieves target plasma concentration rapidly because it is calculated from the volume of distribution, independent of clearance or half-life', true, 'Correct. Loading dose = target concentration x volume of distribution (Vd). Because it depends on Vd rather than clearance, a loading dose can rapidly achieve a desired plasma concentration regardless of how long the drug would otherwise take to reach steady state through maintenance dosing alone (which depends on half-life, typically requiring about 4-5 half-lives). This is why digoxin, like other drugs with a narrow therapeutic index and long half-life, is given as a loading dose (often in divided doses) when rapid effect is needed.', 3),
('d1000000-0000-0000-0000-000000000025', 'D', 'A loading dose is only relevant for drugs with a short half-life', false, 'Ruled out because loading doses are particularly useful for drugs with a long half-life (like digoxin, amiodarone), where waiting for steady state via maintenance dosing alone would take an impractically long time (many days to weeks); for short half-life drugs, steady state is reached quickly with maintenance dosing alone.', 4),
('d1000000-0000-0000-0000-000000000025', 'E', 'A loading dose reduces the risk of toxicity compared with maintenance dosing', false, 'Ruled out because loading doses, by rapidly achieving higher plasma concentrations, can actually increase the immediate risk of toxicity (e.g. digoxin toxicity) if not carefully calculated and monitored; they are used for speed of onset, not for reducing toxicity risk.', 5),
('d1000000-0000-0000-0000-000000000026', 'A', 'This represents a normal first-order dose-proportional increase in level', false, 'Ruled out because a first-order (linear) relationship would predict a level rise roughly proportional to the modest dose increase (300 to 350 mg, about 17%); a more-than-doubling of the level indicates non-linear, zero-order kinetics, not simple proportional first-order behaviour.', 1),
('d1000000-0000-0000-0000-000000000026', 'B', 'The patient has developed enzyme induction from chronic phenytoin use, raising her level', false, 'Ruled out because enzyme induction (which phenytoin itself can cause for other drugs, and CYP induction of its own metabolism can occur but is a different phenomenon) would tend to lower, not raise, plasma levels by increasing clearance; the observed disproportionate rise is explained by saturation kinetics, not induction.', 2),
('d1000000-0000-0000-0000-000000000026', 'C', 'Phenytoin exhibits zero-order (saturable) kinetics at higher concentrations, so small dose increases can produce disproportionately large rises in plasma level', true, 'Correct. Phenytoin metabolism is saturable: at low concentrations it follows first-order kinetics (proportional dose-to-level relationship), but as hepatic enzyme capacity becomes saturated near the therapeutic range, it shifts to zero-order kinetics, where a constant amount (rather than a constant proportion) of drug is metabolised per unit time. This means that once metabolism is saturated, even small dose increases can cause disproportionately large, unpredictable rises in plasma concentration, as seen here.', 3),
('d1000000-0000-0000-0000-000000000026', 'D', 'Phenytoin has poor oral bioavailability, and this represents a formulation-related absorption problem', false, 'Ruled out because phenytoin generally has good oral bioavailability, and the scenario describes a predictable pharmacokinetic phenomenon (saturation of metabolism) rather than an absorption issue.', 4),
('d1000000-0000-0000-0000-000000000026', 'E', 'This indicates non-adherence with the new higher dose, and the patient has been overdosing herself', false, $x$Ruled out because the described pattern (disproportionate rise in level after a small dose increase) is the well-recognised pharmacokinetic signature of phenytoin's zero-order kinetics near the therapeutic range, and does not require invoking non-adherence as an explanation.$x$, 5),
('d1000000-0000-0000-0000-000000000027', 'A', 'Plasma protein binding, because lidocaine clearance depends predominantly on unbound fraction changes with hypoalbuminaemia', false, 'Ruled out because for high-extraction-ratio drugs like lidocaine, clearance is largely independent of protein binding changes (unlike low-extraction-ratio drugs, where protein binding changes matter more); hepatic blood flow is the dominant determinant here.', 1),
('d1000000-0000-0000-0000-000000000027', 'B', 'Renal clearance, because lidocaine is primarily eliminated unchanged by the kidneys', false, 'Ruled out because lidocaine undergoes extensive hepatic metabolism (to active metabolites) rather than significant renal elimination of unchanged drug; hepatic factors, not renal function, are the key determinant of its clearance.', 2),
('d1000000-0000-0000-0000-000000000027', 'C', 'Gastrointestinal absorption, because oral bioavailability is the main determinant of dosing in this context', false, 'Ruled out because intravenous lidocaine is being used here, bypassing oral absorption entirely; the relevant pharmacokinetic issue is hepatic clearance (flow-dependent), not absorption.', 3),
('d1000000-0000-0000-0000-000000000027', 'D', 'Renal tubular secretion competition with other co-administered drugs', false, $x$Ruled out because this does not reflect lidocaine's primary elimination pathway, which is hepatic metabolism; the dominant issue in cirrhosis is reduced hepatic blood flow reducing clearance of this high-extraction drug.$x$, 4),
('d1000000-0000-0000-0000-000000000027', 'E', 'Hepatic blood flow, because lidocaine is a high hepatic-extraction-ratio drug whose clearance is flow-limited rather than enzyme-limited', true, 'Correct. Lidocaine has a high hepatic extraction ratio, meaning that under normal conditions nearly all of the drug delivered to the liver is metabolised in a single pass. For such flow-limited drugs, clearance depends primarily on hepatic blood flow rather than intrinsic enzyme activity or protein binding; in cirrhosis, reduced hepatic blood flow (and portosystemic shunting bypassing the liver entirely) substantially reduces lidocaine clearance, necessitating significant dose reduction to avoid toxicity (e.g. seizures, arrhythmia).', 5),
('d1000000-0000-0000-0000-000000000028', 'A', 'Time to steady state can be shortened simply by increasing the maintenance dose without loading', false, 'Ruled out because increasing the maintenance dose changes the steady-state concentration achieved, not the time taken to reach it, which remains governed by half-life alone; only a loading dose (or infusion) can accelerate achievement of therapeutic concentrations.', 1),
('d1000000-0000-0000-0000-000000000028', 'B', $x$Time to steady state depends only on the drug's half-life, and given amiodarone's half-life of several weeks, steady state may take months to achieve without a loading strategy$x$, true, $x$Correct. Time to reach steady state depends solely on a drug's half-life (approximately 4-5 half-lives), regardless of the dose or dosing interval used. Amiodarone has an extremely long and variable elimination half-life (often 25-60 days, sometimes longer due to extensive tissue accumulation, particularly in fat), meaning that without a loading dose regimen, it could take months for a dose adjustment to reach a new steady-state plasma concentration — this is precisely why amiodarone is initiated with a loading regimen to achieve therapeutic effect more quickly.$x$, 2),
('d1000000-0000-0000-0000-000000000028', 'C', 'Steady state is reached within 24 hours of starting maintenance dosing, regardless of half-life', false, 'Ruled out because this is only true for drugs with very short half-lives; amiodarone, with a half-life measured in weeks, would take vastly longer than 24 hours to reach steady state through maintenance dosing alone.', 3),
('d1000000-0000-0000-0000-000000000028', 'D', $x$Steady state depends primarily on the drug's volume of distribution rather than half-life$x$, false, 'Ruled out because volume of distribution determines loading dose requirements and influences half-life (since half-life = 0.693 x Vd / clearance), but time to steady state itself is a function of half-life directly, not Vd in isolation.', 4),
('d1000000-0000-0000-0000-000000000028', 'E', 'Steady state cannot be achieved for drugs with extensive tissue accumulation such as amiodarone', false, 'Ruled out because steady state can still be achieved for amiodarone, but it takes a very long time (months) due to its long half-life and extensive tissue distribution; a loading regimen is used clinically to shorten the time to therapeutic effect rather than because steady state is unattainable.', 5),
('d1000000-0000-0000-0000-000000000029', 'A', 'Ibuprofen has displaced highly protein-bound warfarin from albumin, increasing the free (active) drug fraction and pharmacological effect despite an unchanged total concentration', true, $x$Correct. Warfarin is highly (~99%) protein-bound, and its pharmacological effect relates to the free (unbound) fraction. In hypoalbuminaemia, baseline free fraction is already increased due to reduced binding sites; the addition of ibuprofen, which competes for the same albumin binding sites, displaces further warfarin, increasing the free fraction and hence anticoagulant effect, even though the total (bound + free) plasma warfarin concentration — which most standard assays measure — remains within the usual range. This combination also carries added bleeding risk from ibuprofen's independent antiplatelet and gastric mucosal effects.$x$, 1),
('d1000000-0000-0000-0000-000000000029', 'B', 'Ibuprofen has induced hepatic warfarin metabolism, increasing anticoagulant effect', false, 'Ruled out because enzyme induction would tend to increase clearance and reduce, not increase, anticoagulant effect; the mechanism here relates to protein binding displacement, not enzyme induction (and NSAIDs are not typically significant CYP inducers of warfarin metabolism).', 2),
('d1000000-0000-0000-0000-000000000029', 'C', 'Ibuprofen has reduced renal clearance of warfarin, causing accumulation', false, 'Ruled out because warfarin is eliminated primarily via hepatic metabolism, not significant renal excretion of unchanged drug, so altered renal clearance is not the relevant mechanism; the key issue here is protein binding displacement in the context of hypoalbuminaemia.', 3),
('d1000000-0000-0000-0000-000000000029', 'D', 'The total warfarin concentration must be measured incorrectly, as an unchanged total level cannot explain increased effect', false, 'Ruled out because this is exactly the expected pharmacokinetic phenomenon in protein-binding displacement interactions: total concentration (which is what is usually measured) can remain unchanged while the pharmacologically active free fraction rises, producing enhanced clinical effect without a corresponding rise in total drug level.', 4),
('d1000000-0000-0000-0000-000000000029', 'E', 'This represents a pharmacodynamic idiosyncratic reaction unrelated to pharmacokinetics', false, 'Ruled out because there is a well-described pharmacokinetic mechanism (albumin-binding site competition, more pronounced with pre-existing hypoalbuminaemia) that adequately explains this presentation, rather than an idiosyncratic pharmacodynamic reaction.', 5),
('d1000000-0000-0000-0000-000000000030', 'A', 'Propranolol is poorly absorbed from the gastrointestinal tract, explaining the need for a much higher oral dose', false, 'Ruled out because propranolol is actually well absorbed from the gut (near-complete absorption); the low oral bioavailability results from extensive first-pass hepatic metabolism after absorption, not poor absorption itself.', 1),
('d1000000-0000-0000-0000-000000000030', 'B', 'Intravenous propranolol has a different volume of distribution to oral propranolol, explaining the dose difference', false, $x$Ruled out because volume of distribution is a property of the drug's distribution into tissues and is essentially the same regardless of route once the drug reaches the systemic circulation; it does not explain the oral/IV dose disparity, which is due to first-pass metabolism (bioavailability).$x$, 2),
('d1000000-0000-0000-0000-000000000030', 'C', 'Oral propranolol undergoes significant renal elimination before reaching the systemic circulation, unlike IV propranolol', false, 'Ruled out because renal elimination is not part of the first-pass phenomenon (which relates to hepatic and, to a lesser extent, gut wall metabolism prior to reaching the systemic circulation), and this is not the explanation for the oral/IV dose difference.', 3),
('d1000000-0000-0000-0000-000000000030', 'D', 'Propranolol undergoes extensive hepatic first-pass metabolism after oral absorption, so only a fraction of the oral dose reaches the systemic circulation, whereas the IV route bypasses this entirely', true, 'Correct. Propranolol has low oral bioavailability (roughly 25%, though variable) due to extensive first-pass hepatic metabolism — a large proportion of an absorbed oral dose is metabolised by the liver before reaching the systemic circulation. Intravenous administration bypasses the gut and first-pass hepatic metabolism entirely, delivering the full dose directly into the systemic circulation, so a much smaller IV dose achieves an equivalent systemic exposure/effect compared with the oral dose.', 4),
('d1000000-0000-0000-0000-000000000030', 'E', $x$Propranolol's half-life differs between oral and intravenous administration, explaining the dose difference$x$, false, 'Ruled out because elimination half-life is a property of clearance and volume of distribution once the drug is in the systemic circulation and does not fundamentally differ by route; the oral/IV dose difference is explained by first-pass metabolism (bioavailability), not by a change in half-life.', 5),
('d1000000-0000-0000-0000-000000000031', 'A', 'The infant independently metabolised codeine to morphine at a toxic rate, unrelated to maternal genotype', false, $x$Ruled out because the mechanism is maternal ultra-rapid conversion of codeine to morphine, with excess morphine then transferred via breast milk; the infant's own codeine metabolism is not the primary issue described in this well-documented phenomenon (though neonates also have reduced morphine clearance, compounding the risk).$x$, 1),
('d1000000-0000-0000-0000-000000000031', 'B', 'Codeine crosses into breast milk unchanged and is directly toxic to neonates regardless of maternal metabolism', false, 'Ruled out because the key mechanism relevant to this specific, well-documented syndrome is excessive maternal conversion of codeine to morphine (via CYP2D6 ultra-rapid metabolism) with morphine (not codeine itself) being the agent causing toxicity via breast milk transfer.', 2),
('d1000000-0000-0000-0000-000000000031', 'C', 'Codeine is a prodrug requiring CYP2D6-mediated conversion to morphine; ultra-rapid metaboliser status caused excessive maternal morphine production, leading to high levels in breast milk and infant opioid toxicity', true, 'Correct. Codeine itself has weak analgesic activity and is metabolised by CYP2D6 to morphine, its active metabolite. In CYP2D6 ultra-rapid metabolisers (a recognised pharmacogenomic phenotype, more common in certain populations), this conversion is markedly accelerated, producing much higher-than-expected maternal morphine concentrations. This morphine is then excreted into breast milk in higher-than-normal amounts, and in a neonate (who also has reduced capacity to clear morphine), this can cause life-threatening or fatal opioid toxicity — the mechanism behind documented case reports and subsequent restriction of codeine use in breastfeeding mothers.', 3),
('d1000000-0000-0000-0000-000000000031', 'D', 'This represents a normal, expected level of infant opioid exposure from maternal codeine use', false, 'Ruled out because this represents a recognised, serious, life-threatening adverse outcome specifically linked to maternal CYP2D6 ultra-rapid metaboliser status, not a normal or expected level of exposure — hence current guidance advises against routine codeine use in breastfeeding mothers.', 4),
('d1000000-0000-0000-0000-000000000031', 'E', 'Maternal renal impairment has led to codeine accumulation and secondary neonatal toxicity', false, 'Ruled out because there is no indication of maternal renal impairment here; the described and well-recognised mechanism is a pharmacogenomic one (CYP2D6 ultra-rapid metabolism) causing excess morphine production, not a renal clearance issue.', 5),
('d1000000-0000-0000-0000-000000000032', 'A', 'Reduce the individual dose while keeping the same dosing interval', false, 'Ruled out because reducing the dose (rather than extending the interval) risks failing to achieve an adequate peak concentration needed for aminoglycoside bactericidal activity (which is concentration-dependent); the issue here is inadequate clearance between doses (elevated trough), best addressed by lengthening the interval.', 1),
('d1000000-0000-0000-0000-000000000032', 'B', 'Increase the dose and shorten the dosing interval to increase bactericidal effect', false, 'Ruled out because increasing dose frequency and amount in a patient already showing impaired clearance (elevated trough) would risk significant drug accumulation and toxicity (nephrotoxicity, ototoxicity), which is the opposite of the appropriate adjustment.', 2),
('d1000000-0000-0000-0000-000000000032', 'C', 'Stop gentamicin monitoring, as a single satisfactory peak level confirms adequate dosing throughout treatment', false, 'Ruled out because ongoing monitoring (particularly trough levels) is essential throughout aminoglycoside therapy, especially in renal impairment, as clearance can change and accumulation risk is high; a single early peak level does not confirm ongoing appropriateness of the regimen.', 3),
('d1000000-0000-0000-0000-000000000032', 'D', 'Switch to a different aminoglycoside with a shorter half-life to avoid the need for interval adjustment', false, 'Ruled out because switching aminoglycoside class does not resolve the fundamental issue of reduced renal clearance in this patient; the correct response to elevated trough levels with adequate peaks is to extend the dosing interval of the current regimen, not to swap agents.', 4),
('d1000000-0000-0000-0000-000000000032', 'E', 'Extend the dosing interval while keeping the individual dose similar, guided by further level monitoring', true, 'Correct. An adequate peak with a raised trough indicates that the dose itself achieves appropriate bactericidal concentrations, but the drug is not being cleared adequately between doses — consistent with reduced renal clearance in this patient with significant renal impairment. The appropriate adjustment is to extend the dosing interval (rather than reduce the dose itself, which would risk sub-therapeutic peak concentrations and reduced bactericidal effect), with further trough (and peak, if needed) level monitoring to guide subsequent dosing.', 5),
('d1000000-0000-0000-0000-000000000033', 'A', 'Plot the paracetamol level on the treatment nomogram and treat only if above the treatment line', false, 'Ruled out because the nomogram is invalid for staggered ingestions, where the time course of absorption is unclear and cannot reliably be related to a single plasma level; treatment decisions in staggered overdose are based on clinical assessment, total dose taken, and evidence of hepatotoxicity, not nomogram plotting.', 1),
('d1000000-0000-0000-0000-000000000033', 'B', 'Discharge with outpatient blood test follow-up, as the paracetamol level is relatively low', false, 'Ruled out because there is already biochemical evidence of early hepatotoxicity (rising ALT, mildly raised INR) in the context of a staggered overdose; this patient requires admission and treatment, not outpatient follow-up.', 2),
('d1000000-0000-0000-0000-000000000033', 'C', 'Withhold treatment until 24 hours have elapsed from the last ingestion, consistent with single-overdose protocols', false, 'Ruled out because in a staggered overdose with evidence of hepatotoxicity, treatment should not be delayed; the 24-hour/nomogram-based framework applies to single acute ingestions with a known ingestion time, not to staggered overdoses.', 3),
('d1000000-0000-0000-0000-000000000033', 'D', 'Start N-acetylcysteine immediately, as the nomogram does not apply to staggered ingestions and there is already biochemical evidence of hepatotoxicity', true, 'Correct. The standard paracetamol treatment nomogram is only valid for a single, acute ingestion with a known, accurate time; it cannot be used to guide treatment in a staggered or repeated supratherapeutic ingestion over time. In staggered overdoses, current UK guidance is to treat with N-acetylcysteine if there is any evidence of possible hepatotoxicity (as here, with a rising ALT and mildly deranged INR) or if the total dose ingested raises concern (e.g. >150 mg/kg over 24 hours, or any staggered overdose with a concerning history), rather than relying on a single paracetamol level plotted against the nomogram.', 4),
('d1000000-0000-0000-0000-000000000033', 'E', 'Perform gastric decontamination with activated charcoal as the priority intervention', false, 'Ruled out because with the last ingestion 4 hours ago in the context of a staggered overdose over 36 hours and ongoing absorption uncertainty, activated charcoal is unlikely to provide significant benefit and is not the priority; N-acetylcysteine should be started given the evidence of hepatotoxicity.', 5),
('d1000000-0000-0000-0000-000000000034', 'A', 'Start urinary alkalinisation with intravenous sodium bicarbonate as the sole definitive treatment', false, $x$Ruled out because urinary alkalinisation, while a useful adjunct in moderate salicylate poisoning to enhance renal elimination, is inadequate as sole therapy in this severe presentation with CNS involvement, very high level, and renal impairment; haemodialysis is indicated and is also more effective than alkalinisation alone in this context, and alkalinisation may be limited by the patient's renal impairment.$x$, 1),
('d1000000-0000-0000-0000-000000000034', 'B', 'Arrange urgent haemodialysis given the severity markers (very high salicylate level, altered mental status, renal impairment, severe acidosis)', true, 'Correct. Haemodialysis is indicated in severe salicylate poisoning when there are features such as a very high salicylate level (often quoted as >700 mg/L, or >500-600 mg/L with severe features), altered mental status/coma, severe or refractory acidosis, pulmonary oedema, or renal failure — several of which are present here. Dialysis both removes salicylate effectively and corrects the acid-base and renal abnormalities more rapidly than supportive measures alone.', 2),
('d1000000-0000-0000-0000-000000000034', 'C', 'Give activated charcoal as the priority intervention at 8 hours post-ingestion', false, 'Ruled out because although activated charcoal (including repeat or multiple-dose charcoal) may have some role earlier or with ongoing absorption in salicylate poisoning, at this stage the priority in a patient with severe toxicity is definitive treatment with haemodialysis, not decontamination alone.', 3),
('d1000000-0000-0000-0000-000000000034', 'D', 'Correct the acidosis with mechanical hyperventilation and intubation as first-line management', false, $x$Ruled out because the patient's tachypnoea and respiratory alkalosis component are a compensatory response that helps maintain a less acidic (and hence less toxic, as salicylate crosses the blood-brain barrier more readily when acidotic) plasma pH; intubation and sedation can precipitate acute deterioration by removing this compensatory hyperventilation, and should be avoided unless absolutely necessary, with haemodialysis being the definitive treatment.$x$, 4),
('d1000000-0000-0000-0000-000000000034', 'E', 'Discharge once the salicylate level begins to trend down on repeat testing', false, 'Ruled out because this patient has severe salicylate poisoning with multiple markers of severity requiring urgent inpatient treatment (haemodialysis), not discharge; salicylate absorption can also be delayed/prolonged (enteric-coated preparations, bezoar formation), so ongoing monitoring is essential.', 5),
('d1000000-0000-0000-0000-000000000035', 'A', 'Give intravenous sodium bicarbonate', true, 'Correct. This presentation (widened QRS, hypotension, arrhythmia, reduced consciousness) reflects tricyclic antidepressant cardiotoxicity, mediated by sodium channel blockade. Intravenous sodium bicarbonate is the definitive treatment, working by increasing extracellular sodium concentration (overcoming sodium channel blockade) and alkalinising the plasma (reducing the proportion of active, protonated drug and enhancing protein binding), which narrows the QRS complex and reduces arrhythmia risk; it is indicated for QRS prolongation >100-120 ms, arrhythmia, or hypotension in TCA overdose.', 1),
('d1000000-0000-0000-0000-000000000035', 'B', 'Give intravenous flecainide to control the wide-complex tachycardia', false, 'Ruled out because class Ia and Ic antiarrhythmics (which also block sodium channels) are contraindicated in TCA overdose, as they would worsen the existing sodium channel blockade and cardiotoxicity; sodium bicarbonate is the treatment of choice.', 2),
('d1000000-0000-0000-0000-000000000035', 'C', 'Give intravenous calcium gluconate to stabilise the myocardium', false, 'Ruled out because calcium gluconate is used for hyperkalaemia-related cardiotoxicity, not TCA-induced sodium channel blockade; sodium bicarbonate is the specific and effective treatment for TCA cardiotoxicity.', 3),
('d1000000-0000-0000-0000-000000000035', 'D', 'Perform immediate synchronised DC cardioversion regardless of haemodynamic response to other measures', false, 'Ruled out because the underlying problem is sodium channel blockade, which is best addressed pharmacologically with sodium bicarbonate first; cardioversion may be needed if there is haemodynamic collapse or pulseless arrhythmia, but is not the first-line treatment for TCA-induced wide-complex tachycardia with a preserved (if low) blood pressure.', 4),
('d1000000-0000-0000-0000-000000000035', 'E', 'Give intravenous magnesium sulfate as first-line treatment for the arrhythmia', false, 'Ruled out because although magnesium may have a role in refractory TCA-associated arrhythmias (particularly torsades-type rhythms), sodium bicarbonate is the first-line, most effective specific treatment for TCA-induced QRS widening and arrhythmia, targeting the underlying sodium channel blockade.', 5),
('d1000000-0000-0000-0000-000000000036', 'A', 'Give intravenous furosemide to enhance urinary lithium excretion', false, 'Ruled out because loop diuretics can actually increase lithium reabsorption (via volume depletion driving compensatory proximal tubular reabsorption) and worsen toxicity; volume repletion with isotonic saline, not diuretics, is the supportive measure of choice, alongside haemodialysis given the severity here.', 1),
('d1000000-0000-0000-0000-000000000036', 'B', 'Withhold lithium and manage conservatively with oral fluids only, as levels will fall over several days', false, 'Ruled out because this patient has severe symptomatic toxicity with a very high level, renal impairment and inability to tolerate oral intake; conservative oral management is inadequate and haemodialysis is indicated to prevent life-threatening neurological deterioration.', 2),
('d1000000-0000-0000-0000-000000000036', 'C', 'Give intravenous 0.9% sodium chloride and arrange urgent haemodialysis', true, 'Correct. This represents severe, symptomatic chronic (or acute-on-chronic) lithium toxicity, precipitated by dehydration and renal impairment reducing lithium clearance. Management includes generous intravenous 0.9% sodium chloride to correct volume depletion and enhance renal lithium clearance, but with severe neurological symptoms (confusion, ataxia), a very high level (>2.5-3.5 mmol/L in chronic toxicity, especially with renal impairment or severe symptoms), and inability to tolerate oral intake, haemodialysis is indicated as it is the most effective way to rapidly remove lithium and prevent progression to seizures, coma or death.', 3),
('d1000000-0000-0000-0000-000000000036', 'D', 'Give sodium bicarbonate to enhance renal lithium clearance', false, 'Ruled out because urinary alkalinisation enhances elimination of weak acids (such as salicylates), not lithium, which is a small cation eliminated by glomerular filtration and tubular reabsorption/handling similar to sodium; it has no established role in lithium toxicity management.', 4),
('d1000000-0000-0000-0000-000000000036', 'E', 'Give activated charcoal to reduce ongoing lithium absorption', false, 'Ruled out because activated charcoal does not bind lithium (an inorganic ion) and has no role in its decontamination; management centres on volume repletion and, in severe cases, haemodialysis.', 5),
('d1000000-0000-0000-0000-000000000037', 'A', 'Give intravenous calcium gluconate to treat the hyperkalaemia', false, $x$Ruled out because intravenous calcium is relatively contraindicated in digoxin toxicity, as it can theoretically worsen cardiac toxicity (via further raising intracellular calcium in digoxin-toxic, already calcium-overloaded myocytes) — sometimes referred to as causing a 'stone heart'; DigiFab is the appropriate treatment, which will also help correct the hyperkalaemia by reversing the underlying pump inhibition.$x$, 1),
('d1000000-0000-0000-0000-000000000037', 'B', 'Give digoxin-specific antibody fragments (DigiFab)', true, 'Correct. This is severe digoxin toxicity with life-threatening features: significant arrhythmia (bidirectional VT is a classically described digoxin-toxic rhythm), hyperkalaemia (a marker of severity in acute/acute-on-chronic digoxin toxicity, reflecting inhibition of the Na+/K+-ATPase pump), and renal impairment reducing digoxin clearance. Digoxin-specific antibody fragments are indicated for life-threatening arrhythmia, severe hyperkalaemia, or very high digoxin levels in this context, and work by binding free digoxin, rapidly reducing the active drug available to inhibit the Na+/K+-ATPase pump.', 2),
('d1000000-0000-0000-0000-000000000037', 'C', 'Give insulin-dextrose infusion alone to manage the hyperkalaemia without addressing digoxin toxicity', false, 'Ruled out because while insulin-dextrose can be used adjunctively for hyperkalaemia, the underlying life-threatening problem is digoxin toxicity itself (causing both the arrhythmia and the hyperkalaemia via pump inhibition); DigiFab addresses the root cause and is the priority treatment, and treating hyperkalaemia while continuing significant free digoxin exposure would not resolve the life-threatening arrhythmia risk.', 3),
('d1000000-0000-0000-0000-000000000037', 'D', 'Perform urgent haemodialysis to remove digoxin', false, 'Ruled out because digoxin has a very large volume of distribution and is poorly removed by haemodialysis; DigiFab is the definitive treatment for severe digoxin toxicity, not dialysis (though dialysis may still be needed separately for renal failure management if it persists).', 4),
('d1000000-0000-0000-0000-000000000037', 'E', 'Withhold digoxin and observe, as levels will fall as renal function recovers', false, 'Ruled out because this patient has life-threatening features (malignant arrhythmia, severe hyperkalaemia) requiring immediate specific treatment with DigiFab; simply withholding the drug and observing is inadequate given the acuity and severity of this presentation.', 5),
('d1000000-0000-0000-0000-000000000038', 'A', 'Give intravenous glucagon', true, 'Correct. In beta-blocker overdose with haemodynamic compromise unresponsive to atropine, intravenous glucagon is the specific antidote of choice. Glucagon activates myocardial adenylate cyclase via a separate (non-beta-adrenergic) receptor, bypassing the blocked beta-receptor and increasing intracellular cAMP, thereby improving heart rate and contractility independent of beta-receptor blockade.', 1),
('d1000000-0000-0000-0000-000000000038', 'B', 'Give a further, higher dose of intravenous atropine and wait for response', false, 'Ruled out because atropine has already had minimal effect, reflecting that the bradycardia in beta-blocker overdose is due to beta-receptor blockade rather than predominantly vagal mechanisms; escalating atropine alone is unlikely to be effective, and glucagon (or other measures such as high-dose insulin-euglycaemia therapy) should be used.', 2),
('d1000000-0000-0000-0000-000000000038', 'C', 'Start an infusion of a beta-agonist such as salbutamol as first-line treatment', false, 'Ruled out because beta-agonists act at the same (blocked) beta-receptor and are often ineffective in significant beta-blocker overdose; glucagon bypasses the beta-receptor via a separate signalling pathway and is preferred as an initial specific treatment, with other measures like high-dose insulin-euglycaemia therapy or adrenaline used in refractory cases.', 3),
('d1000000-0000-0000-0000-000000000038', 'D', 'Perform immediate transvenous pacing without trying pharmacological measures first', false, 'Ruled out because pharmacological treatment (glucagon, and if needed high-dose insulin-euglycaemia therapy, inotropic support) is tried first in beta-blocker overdose; pacing may be considered for refractory bradycardia but capture can be difficult and it is not the first-line intervention here.', 4),
('d1000000-0000-0000-0000-000000000038', 'E', 'Give intravenous calcium gluconate as the definitive treatment for beta-blocker toxicity', false, 'Ruled out because calcium is the more specific antidote for calcium channel blocker overdose rather than beta-blocker overdose; while calcium may have some adjunctive benefit in mixed or severe cases, glucagon is the primary specific treatment here.', 5),
('d1000000-0000-0000-0000-000000000039', 'A', 'Give a further, larger bolus of intravenous calcium gluconate and repeat as needed indefinitely', false, 'Ruled out because although calcium can transiently overcome calcium channel blockade, its effect is often short-lived and repeated large doses carry risks (hypercalcaemia, tissue necrosis with extravasation); when the response is inadequate, escalation to high-dose insulin-euglycaemia therapy (and/or other inotropes, lipid emulsion, or extracorporeal support) is indicated rather than simply repeating calcium indefinitely.', 1),
('d1000000-0000-0000-0000-000000000039', 'B', 'Start an infusion of a beta-agonist such as isoprenaline as first-line escalation', false, 'Ruled out because catecholamine inotropes/vasopressors are often relatively ineffective as monotherapy in severe CCB overdose (due to CCB-induced impaired calcium influx also affecting catecholamine responsiveness) and are generally used adjunctively rather than as the definitive next escalation step; high-dose insulin-euglycaemia therapy has a stronger evidence base as the next step here.', 2),
('d1000000-0000-0000-0000-000000000039', 'C', 'Perform emergency haemodialysis to remove amlodipine', false, 'Ruled out because amlodipine (and most calcium channel blockers) are highly protein-bound and have a large volume of distribution, making them poorly dialysable; haemodialysis is not an effective treatment for CCB overdose, and management relies on supportive/pharmacological measures such as HIET.', 3),
('d1000000-0000-0000-0000-000000000039', 'D', 'Start high-dose insulin-euglycaemia therapy', true, 'Correct. In calcium channel blocker overdose with cardiogenic shock refractory to fluids and calcium, high-dose insulin-euglycaemia therapy (HIET) is the treatment of choice. Insulin improves myocardial contractility by promoting carbohydrate utilisation as the preferred myocardial energy substrate (a shift favoured during CCB toxicity) and has a direct positive inotropic effect, alongside vasodilatory benefit; it requires concurrent dextrose infusion and close glucose/potassium monitoring.', 4),
('d1000000-0000-0000-0000-000000000039', 'E', 'Give intravenous glucagon as the definitive specific antidote for calcium channel blocker toxicity', false, 'Ruled out because glucagon is the specific antidote for beta-blocker overdose, not calcium channel blocker overdose; while it may occasionally be tried adjunctively, high-dose insulin-euglycaemia therapy has a much stronger evidence base as the next step in refractory CCB toxicity.', 5),
('d1000000-0000-0000-0000-000000000040', 'A', 'Discharge immediately, as full and rapid response to naloxone confirms the episode has resolved', false, $x$Ruled out because a rapid initial response to naloxone does not exclude the risk of subsequent renarcotisation once the naloxone effect wears off, particularly given naloxone's shorter duration of action relative to the opioid ingested; immediate discharge risks a fatal recurrence of respiratory depression.$x$, 1),
('d1000000-0000-0000-0000-000000000040', 'B', 'Start a naloxone infusion only if the patient re-arrests, rather than proactively', false, 'Ruled out because in overdoses with ongoing renarcotisation risk (e.g. large doses, long-acting opioids, or recurrent desaturation), a naloxone infusion may be started proactively rather than waiting for a further life-threatening event; regardless, a period of monitoring/observation is required before considering discharge.', 2),
('d1000000-0000-0000-0000-000000000040', 'C', 'Give a single additional intramuscular dose of naloxone and discharge immediately afterwards', false, $x$Ruled out because even with an additional dose, naloxone's effect will still wear off within a limited timeframe; ongoing clinical observation (not just an extra dose followed by immediate discharge) is needed to monitor for renarcotisation.$x$, 3),
('d1000000-0000-0000-0000-000000000040', 'D', 'Arrange psychiatric assessment as the priority before any medical monitoring', false, 'Ruled out because the immediate priority is medical monitoring for renarcotisation risk following opioid overdose reversal; psychiatric/substance misuse assessment and support are important but follow adequate medical observation, not precede it.', 4),
('d1000000-0000-0000-0000-000000000040', 'E', $x$Advise a period of observation of several hours, as naloxone's duration of action is shorter than that of heroin and renarcotisation (recurrence of respiratory depression) is a significant risk$x$, true, $x$Correct. Naloxone has a relatively short half-life (roughly 30-90 minutes) compared with many opioids, including heroin's active metabolite morphine and particularly longer-acting opioids; as naloxone's effect wears off, respiratory depression can recur (renarcotisation) even after apparent full recovery. Patients should be observed for an adequate period (commonly at least 2-4 hours after the last naloxone dose, individualised to the opioid involved and clinical response) before considering discharge, given the risk of this potentially fatal recurrence.$x$, 5),
('d1000000-0000-0000-0000-000000000041', 'A', 'Give fomepizole (or ethanol if fomepizole is unavailable) to inhibit alcohol dehydrogenase, alongside consideration of haemodialysis', true, 'Correct. Ethylene glycol is metabolised by alcohol dehydrogenase to toxic metabolites (including glycolic and oxalic acid), which cause the severe anion gap metabolic acidosis and, via calcium oxalate crystal deposition, renal injury seen here. Fomepizole competitively inhibits alcohol dehydrogenase, preventing further toxic metabolite formation, and is the preferred antidote (ethanol is an alternative if fomepizole is unavailable, working via the same competitive mechanism but requiring more intensive monitoring). Haemodialysis is added for severe poisoning (significant acidosis, renal impairment, or very high levels) as it removes both the parent compound and toxic metabolites.', 1),
('d1000000-0000-0000-0000-000000000041', 'B', 'Give activated charcoal as the primary treatment', false, 'Ruled out because activated charcoal does not effectively adsorb small, rapidly absorbed alcohols like ethylene glycol, and by 6 hours post-ingestion much of the dose will already have been absorbed; the priority is alcohol dehydrogenase inhibition (fomepizole/ethanol) and consideration of dialysis.', 2),
('d1000000-0000-0000-0000-000000000041', 'C', 'Correct the acidosis with sodium bicarbonate alone and observe without antidote therapy', false, 'Ruled out because bicarbonate may have some adjunctive role in severe acidosis, but without blocking further toxic metabolite formation (via fomepizole or ethanol) and considering removal of toxic metabolites (dialysis in severe cases), the underlying toxic process will continue; specific antidote therapy is required.', 3),
('d1000000-0000-0000-0000-000000000041', 'D', 'Give intravenous calcium gluconate as the definitive treatment to chelate the toxic metabolites', false, 'Ruled out because calcium gluconate is used to treat symptomatic hypocalcaemia (from calcium oxalate deposition) if it occurs, but it is not the definitive treatment for ethylene glycol poisoning; the priority is alcohol dehydrogenase inhibition (fomepizole/ethanol) and consideration of haemodialysis.', 4),
('d1000000-0000-0000-0000-000000000041', 'E', 'Give N-acetylcysteine as the specific antidote for this poisoning', false, 'Ruled out because N-acetylcysteine is the specific antidote for paracetamol poisoning, not ethylene glycol poisoning; the relevant antidote here is fomepizole (or ethanol), which blocks alcohol dehydrogenase-mediated toxic metabolite formation.', 5),
('d1000000-0000-0000-0000-000000000042', 'A', 'Continue all three medications and add a loop diuretic to increase urine output', false, 'Ruled out because continuing all three nephrotoxic-in-combination drugs would perpetuate the renal injury; the priority is to stop the precipitating drugs and support renal recovery, not add a further diuretic which does not address the underlying cause.', 1),
('d1000000-0000-0000-0000-000000000042', 'B', 'Stop ibuprofen and temporarily withhold the ACE inhibitor and diuretic, with intravenous fluid resuscitation as needed and monitoring of renal function', true, $x$Correct. This is NSAID-precipitated acute kidney injury in the context of the 'triple whammy' combination (ACE inhibitor + diuretic + NSAID), where NSAID-mediated reduction in renal prostaglandin synthesis critically impairs afferent arteriolar perfusion, particularly when combined with ACE inhibitor-related efferent arteriolar dilation and diuretic-induced volume depletion. Management is to stop the NSAID, temporarily withhold the ACE inhibitor and diuretic until renal function recovers, and give appropriate fluid resuscitation, with close monitoring of renal function and electrolytes.$x$, 2),
('d1000000-0000-0000-0000-000000000042', 'C', 'Stop only the ACE inhibitor and continue ibuprofen and the diuretic', false, 'Ruled out because the NSAID (ibuprofen) is a key contributor to this presentation via reduced renal prostaglandin-mediated perfusion, and should also be stopped; continuing it would perpetuate the AKI.', 3),
('d1000000-0000-0000-0000-000000000042', 'D', 'Arrange urgent renal biopsy before making any changes to medication', false, 'Ruled out because the clinical picture is characteristic of drug-induced (triple whammy) AKI, which is managed by stopping the causative drugs and supporting renal recovery; biopsy is not required for this classic presentation and would inappropriately delay treatment.', 4),
('d1000000-0000-0000-0000-000000000042', 'E', 'Start renal replacement therapy immediately regardless of biochemical or clinical severity', false, 'Ruled out because there is no indication given here (such as refractory hyperkalaemia, severe acidosis, fluid overload, or uraemic complications) that renal replacement therapy is immediately required; initial management should focus on stopping causative drugs and supportive fluid management, reserving dialysis for standard indications if renal function does not recover.', 5),
('d1000000-0000-0000-0000-000000000043', 'A', 'Continue metformin at the same dose, as it has been well tolerated with no gastrointestinal side effects', false, 'Ruled out because gastrointestinal tolerability does not reflect renal clearance or lactic acidosis risk; metformin dose/continuation decisions are based on eGFR thresholds regardless of symptom tolerability, and this eGFR is below the level at which continuation is considered safe.', 1),
('d1000000-0000-0000-0000-000000000043', 'B', 'Halve the metformin dose and continue monitoring renal function every 6 months', false, 'Ruled out because dose halving is the appropriate action at an eGFR of 30-45; below an eGFR of 30 (as here, at 24), metformin is generally stopped altogether rather than merely dose-reduced, given the significantly increased lactic acidosis risk.', 2),
('d1000000-0000-0000-0000-000000000043', 'C', 'Increase the metformin dose to improve glycaemic control given the deteriorating renal function may reflect poor diabetic control', false, 'Ruled out because increasing metformin dose in the context of significant renal impairment would substantially increase lactic acidosis risk; renal function decline should prompt dose reduction/cessation, not escalation.', 3),
('d1000000-0000-0000-0000-000000000043', 'D', 'Switch metformin to the extended-release formulation, which is safe at any level of renal impairment', false, 'Ruled out because extended-release metformin formulations do not have different renal safety thresholds from standard formulations; the same eGFR-based cessation/dose-reduction principles apply regardless of formulation.', 4),
('d1000000-0000-0000-0000-000000000043', 'E', 'Stop metformin, given the eGFR is below the threshold at which it is considered contraindicated', true, 'Correct. Current UK guidance generally advises reviewing metformin dose at eGFR <45 mL/min/1.73m2 (often halving the dose) and stopping it at eGFR <30 mL/min/1.73m2, due to increased risk of lactic acidosis from reduced renal clearance of metformin in significant renal impairment. At an eGFR of 24, metformin should be stopped and alternative glucose-lowering therapy considered, particularly given the drop from a previous eGFR of 55, which also warrants further nephrology work-up to identify a cause for the deterioration.', 5),
('d1000000-0000-0000-0000-000000000044', 'A', 'Increase the codeine dose further, as it is safe in renal impairment', false, 'Ruled out because codeine is metabolised (partly via CYP2D6) to morphine, which carries the same active metabolite accumulation risk in renal impairment, and codeine itself should also be used cautiously or avoided in significant renal impairment; simply increasing the dose risks accumulation and toxicity.', 1),
('d1000000-0000-0000-0000-000000000044', 'B', 'Start regular oral morphine at a standard starting dose, titrating as for a patient with normal renal function', false, $x$Ruled out because morphine's active metabolites accumulate significantly in renal impairment, and standard dosing/titration schedules (designed for normal renal function) risk toxicity including sedation, respiratory depression and neuroexcitatory effects (myoclonus, hyperalgesia) in this patient with an eGFR of 18.$x$, 2),
('d1000000-0000-0000-0000-000000000044', 'C', 'Avoid all opioids in this patient given the degree of renal impairment', false, 'Ruled out because opioids can still be used safely in significant renal impairment with appropriate choice (e.g. fentanyl, cautious oxycodone) and dose adjustment; avoiding opioids altogether would leave his cancer-related bone pain inadequately managed.', 3),
('d1000000-0000-0000-0000-000000000044', 'D', 'Use oxycodone or fentanyl with caution and dose titration, avoiding morphine due to accumulation of active renally-excreted metabolites', true, 'Correct. Morphine is metabolised to active metabolites (morphine-6-glucuronide and morphine-3-glucuronide) that are renally excreted and accumulate in significant renal impairment, risking prolonged sedation, respiratory depression and neurotoxicity (myoclonus, hyperalgesia). In significant renal impairment, opioids with less problematic renally-excreted active metabolites — such as oxycodone (used cautiously, as some metabolite accumulation can still occur) or fentanyl (largely hepatically metabolised to inactive metabolites) — are generally preferred, with cautious dose titration and monitoring.', 4),
('d1000000-0000-0000-0000-000000000044', 'E', 'Use transdermal buprenorphine at a high starting dose without renal-specific dose caution', false, $x$Ranked out because although buprenorphine is often considered relatively favourable in renal impairment (minimal renally-excreted active metabolites), starting at a high dose without appropriate titration is not good practice in any patient, and this option does not represent the most straightforward first-line reasoning here compared with correctly identifying morphine's accumulation risk and preferring oxycodone/fentanyl with cautious titration.$x$, 5),
('d1000000-0000-0000-0000-000000000045', 'A', 'Continue enoxaparin at the standard treatment dose without any monitoring, as LMWH is safe in all degrees of renal impairment', false, 'Ruled out because enoxaparin (and other LMWHs) accumulate significantly at creatinine clearance below 30 mL/min, increasing bleeding risk; dose adjustment or an alternative anticoagulant strategy with appropriate monitoring is required, not unmonitored continuation of the standard dose.', 1),
('d1000000-0000-0000-0000-000000000045', 'B', 'Increase the enoxaparin dose to ensure therapeutic anticoagulation is achieved despite renal impairment', false, 'Ruled out because renal impairment causes drug accumulation (increasing, not decreasing, effective anticoagulant exposure) with standard dosing; increasing the dose further would substantially increase bleeding risk.', 2),
('d1000000-0000-0000-0000-000000000045', 'C', 'Reduce the enoxaparin dose and consider monitoring anti-Xa levels, or use unfractionated heparin as an alternative, given the significant renal impairment', true, 'Correct. Low molecular weight heparins, including enoxaparin, are predominantly renally cleared and accumulate in significant renal impairment (creatinine clearance <30 mL/min), increasing bleeding risk. Standard practice at this level of renal impairment is either dose reduction of enoxaparin with anti-Xa level monitoring to guide dosing, or switching to unfractionated heparin (which is not renally cleared and can be more easily titrated/reversed, particularly useful when rapid dose adjustment or reversal might be needed).', 3),
('d1000000-0000-0000-0000-000000000045', 'D', 'Switch to a direct oral anticoagulant at full treatment dose, as this avoids all renal dosing concerns', false, 'Ruled out because DOACs used for VTE treatment also have renal clearance components and their own eGFR-based dosing/cutoffs (varying by agent), so this does not avoid renal dosing considerations; at this level of renal impairment (CrCl 25), careful agent-specific consideration is needed rather than assuming any DOAC can be used at full dose without caution.', 4),
('d1000000-0000-0000-0000-000000000045', 'E', 'Stop anticoagulation altogether given the degree of renal impairment', false, 'Ruled out because this patient has an acute proximal DVT requiring ongoing anticoagulation to prevent extension and pulmonary embolism; anticoagulation should be continued with an appropriately adjusted regimen (dose-reduced LMWH with monitoring, or unfractionated heparin), not stopped.', 5),
('d1000000-0000-0000-0000-000000000046', 'A', 'Use NSAIDs as first-line analgesia, as they avoid hepatic metabolism concerns', false, 'Ruled out because NSAIDs are relatively contraindicated in decompensated cirrhosis due to bleeding risk (especially with varices/coagulopathy) and the risk of precipitating renal impairment/hepatorenal syndrome, regardless of the fact that they are not primarily hepatically metabolised.', 1),
('d1000000-0000-0000-0000-000000000046', 'B', 'Use full standard-dose codeine regularly, as opioids are not affected by liver disease', false, 'Ruled out because opioids, including codeine, undergo hepatic metabolism and their action is prolonged in significant hepatic impairment, increasing sedation risk and the risk of precipitating hepatic encephalopathy; full standard dosing is inappropriate and cautious, reduced dosing is required.', 2),
('d1000000-0000-0000-0000-000000000046', 'C', 'Use regular paracetamol at a reduced total daily dose, avoid NSAIDs, and use opioids cautiously at reduced doses/frequency with close monitoring for precipitating encephalopathy', true, 'Correct. In decompensated cirrhosis: NSAIDs should be avoided due to risks of gastrointestinal bleeding (compounded by varices/coagulopathy) and precipitating hepatorenal syndrome/AKI; paracetamol can still be used but often at a reduced total daily dose (e.g. maximum 2-3g/day rather than 4g) given reduced hepatic glutathione reserves and metabolic capacity, particularly in malnourished or heavily alcohol-exposed patients; opioids should be used cautiously at reduced doses/extended intervals because reduced hepatic clearance prolongs their action and increases the risk of precipitating or worsening hepatic encephalopathy, with close clinical monitoring.', 3),
('d1000000-0000-0000-0000-000000000046', 'D', 'Use paracetamol at the full standard maximum dose without any adjustment', false, 'Ruled out because in decompensated cirrhosis, particularly with malnutrition or ongoing alcohol use, hepatic glutathione stores and metabolic capacity are reduced, and a lower total daily paracetamol dose is generally recommended as a precaution, though paracetamol remains a reasonable analgesic choice overall.', 4),
('d1000000-0000-0000-0000-000000000046', 'E', 'Avoid all analgesia given the complexity of prescribing in decompensated liver disease', false, 'Ruled out because analgesia can and should still be provided with appropriate drug choice and dose adjustment (reduced-dose paracetamol, cautious low-dose opioids, avoiding NSAIDs); withholding all analgesia is not appropriate management of his pain.', 5),
('d1000000-0000-0000-0000-000000000047', 'A', 'Continue the same dose and interval, as vancomycin levels naturally fluctuate and no action is needed', false, 'Ruled out because a significantly elevated trough with new tinnitus indicates clinically relevant drug accumulation and early ototoxicity; continuing the same regimen risks worsening toxicity, including potentially irreversible hearing loss and worsening renal function.', 1),
('d1000000-0000-0000-0000-000000000047', 'B', 'Withhold the next dose(s) and adjust the dosing regimen (reduced dose and/or extended interval) based on further level monitoring', true, 'Correct. Vancomycin is predominantly renally cleared, and in renal impairment (as here, eGFR 32) standard dosing regimens can lead to drug accumulation, evidenced by the elevated trough level and new tinnitus (an early sign of ototoxicity). Management is to withhold further doses until the level falls to an appropriate range, then resume with an adjusted regimen (reduced dose and/or extended dosing interval), guided by ongoing therapeutic drug monitoring (trough or AUC-based monitoring) to balance efficacy against toxicity (nephrotoxicity, ototoxicity).', 2),
('d1000000-0000-0000-0000-000000000047', 'C', 'Increase the dose to ensure adequate bactericidal levels are maintained', false, 'Ruled out because the trough is already elevated with emerging toxicity; increasing the dose would further raise levels and toxicity risk rather than addressing the accumulation problem.', 3),
('d1000000-0000-0000-0000-000000000047', 'D', 'Switch immediately to oral vancomycin at an equivalent dose', false, 'Ruled out because oral vancomycin is not systemically absorbed to a clinically significant degree (it is used for local action in the gut, e.g. for C. difficile infection) and would not treat a bacteraemia; the correct approach is to adjust the intravenous dosing regimen based on renal function and levels, not switch routes.', 4),
('d1000000-0000-0000-0000-000000000047', 'E', 'Stop vancomycin permanently and do not consider it again for this patient', false, 'Ruled out because vancomycin can often still be used safely and effectively in renal impairment with appropriate dose/interval adjustment and monitoring; permanent discontinuation is not necessary based on a single elevated level with early, reversible signs of toxicity if managed promptly.', 5),
('d1000000-0000-0000-0000-000000000048', 'A', 'Continue atorvastatin at the same dose, as statins are not hepatotoxic', false, 'Ruled out because statins can cause hepatotoxicity (usually mild, transient transaminase elevation, but occasionally more significant) and are contraindicated in active/decompensated liver disease; continuing at the same dose in this context is inappropriate.', 1),
('d1000000-0000-0000-0000-000000000048', 'B', 'Halve the atorvastatin dose and monitor liver function every 3 months', false, 'Ruled out because in decompensated cirrhosis with significantly deranged transaminases (as opposed to mild, stable elevations which might warrant only monitoring or minor dose adjustment), statins are contraindicated altogether rather than simply dose-reduced; the appropriate action is to stop the drug.', 2),
('d1000000-0000-0000-0000-000000000048', 'C', 'Switch to a higher-intensity statin such as rosuvastatin, which is safer in liver disease', false, 'Ruled out because no statin is considered safe to initiate or continue in the context of active, decompensated liver disease with significantly elevated transaminases; switching statins does not resolve the underlying contraindication.', 3),
('d1000000-0000-0000-0000-000000000048', 'D', 'Continue the statin but add ursodeoxycholic acid for hepatoprotection', false, 'Ruled out because there is no evidence that adding ursodeoxycholic acid allows safe continuation of a contraindicated statin in decompensated liver disease; the statin should simply be stopped in this context.', 4),
('d1000000-0000-0000-0000-000000000048', 'E', 'Stop the statin, as active liver disease with significantly elevated transaminases is a contraindication to statin therapy', true, 'Correct. Statins are contraindicated in active liver disease, including unexplained persistent elevations in transaminases and decompensated cirrhosis, due to the risk of further hepatotoxicity and difficulty distinguishing drug-related harm from the underlying liver disease course. With Child-Pugh B decompensated cirrhosis and significantly elevated ALT, the statin should be stopped, and the ongoing need for lipid-lowering therapy reassessed once (or if) liver disease stabilises, in conjunction with hepatology input.', 5),
('d1000000-0000-0000-0000-000000000049', 'A', 'This most likely represents insulin non-adherence, and doses should be increased to compensate for presumed missed doses', false, 'Ruled out because recurrent hypoglycaemia with unchanged administered doses, diet and activity in the context of progressive renal decline is much better explained by reduced renal insulin clearance than presumed non-adherence, and increasing doses would be dangerous and inappropriate.', 1),
('d1000000-0000-0000-0000-000000000049', 'B', 'Renal impairment has no effect on insulin pharmacokinetics, and an alternative cause for the hypoglycaemia should be sought', false, 'Ruled out because renal impairment is a well-recognised cause of altered insulin pharmacokinetics (reduced clearance, prolonged action) and is the most likely explanation here given the clear temporal association with declining renal function; while other causes of hypoglycaemia should always be considered, this is the leading explanation to act on.', 2),
('d1000000-0000-0000-0000-000000000049', 'C', 'Insulin doses should be increased to maintain the same glycaemic target despite renal impairment', false, 'Ruled out because the clinical picture (recurrent hypoglycaemia) already indicates relative over-insulinisation due to reduced clearance; increasing the dose further would worsen hypoglycaemia risk.', 3),
('d1000000-0000-0000-0000-000000000049', 'D', 'Reduced renal clearance of insulin in CKD has increased its effective duration of action and risk of accumulation; insulin doses should be reduced with closer glucose monitoring', true, 'Correct. The kidney plays a significant role in insulin clearance and degradation; as renal function declines, insulin clearance is reduced, prolonging its effective action and increasing the risk of accumulation and hypoglycaemia, even without any change in administered dose, diet or activity. This is a well-recognised phenomenon in progressive CKD and requires proactive insulin dose reduction (often needed as eGFR falls, particularly below around 45-50 mL/min/1.73m2, with further reduction at lower levels) alongside closer glucose monitoring to avoid recurrent hypoglycaemia.', 4),
('d1000000-0000-0000-0000-000000000049', 'E', 'Switch to oral sulfonylurea therapy, which is unaffected by renal function and safer than insulin in CKD', false, 'Ruled out because sulfonylureas (particularly those with active renally-excreted metabolites, such as glibenclamide) also carry increased hypoglycaemia risk in renal impairment and are not inherently safer than appropriately dose-adjusted insulin; if sulfonylureas were to be used, agent selection and dose would still need careful renal consideration.', 5),
('d1000000-0000-0000-0000-000000000050', 'A', 'Switch dabigatran to a DOAC with less renal dependence, such as apixaban, with dose adjustment as indicated, or to warfarin', true, 'Correct. Dabigatran is approximately 80% renally excreted, making it the DOAC most affected by declining renal function and least suitable at lower eGFR levels (generally avoided below an eGFR/CrCl of around 30 mL/min/1.73m2, with caution advised even at 30-50). At a creatinine clearance of 27, dabigatran should be switched to an anticoagulant with less renal dependence, such as apixaban (which has the lowest renal elimination fraction among the DOACs and remains an option at this level, potentially with dose adjustment) or warfarin, which has well-established dosing in significant renal impairment.', 1),
('d1000000-0000-0000-0000-000000000050', 'B', 'Continue dabigatran at the same dose, as renal function does not significantly affect its clearance', false, 'Ruled out because dabigatran is predominantly (around 80%) renally excreted, making it highly sensitive to declining renal function, unlike the other DOACs; continuing at the same dose at this eGFR risks significant drug accumulation and bleeding.', 2),
('d1000000-0000-0000-0000-000000000050', 'C', 'Reduce the dabigatran dose to 110 mg twice daily and continue without further action', false, $x$Ruled out because even the lower dabigatran dose is generally not recommended or is used with great caution at this level of renal impairment (CrCl <30), given the drug's high degree of renal dependence; switching to a less renally-dependent agent is preferred over dose reduction alone at this level.$x$, 3),
('d1000000-0000-0000-0000-000000000050', 'D', 'Stop all anticoagulation, as no anticoagulant can be safely used at this level of renal function', false, 'Ruled out because effective anticoagulation options remain available at this level of renal function (e.g. dose-adjusted apixaban, or warfarin), and stopping anticoagulation altogether in a patient with AF would leave her unprotected against cardioembolic stroke.', 4),
('d1000000-0000-0000-0000-000000000050', 'E', 'Switch dabigatran to rivaroxaban at the standard treatment dose without further renal consideration', false, 'Ruled out because rivaroxaban also has a meaningful renal elimination component and requires dose adjustment/caution as renal function declines; simply switching to another DOAC without considering its own renal dosing requirements is not an adequate response, whereas apixaban (with the least renal dependence) or warfarin are more appropriate choices at this eGFR.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('d1000000-0000-0000-0000-000000000001', 'Amiodarone pulmonary toxicity is a cumulative-dose, duration-dependent adverse effect that can present as organising pneumonia, hypersensitivity pneumonitis, or progressive fibrosis; HRCT typically shows ground-glass change with fibrotic features.', 1),
('d1000000-0000-0000-0000-000000000001', 'Management is drug withdrawal plus corticosteroids for symptomatic or hypoxic patients; because amiodarone has a very long half-life (weeks), toxicity can progress even after the drug is stopped, and steroids are tapered slowly.', 2),
('d1000000-0000-0000-0000-000000000001', 'Amiodarone also causes thyroid dysfunction, corneal microdeposits, hepatotoxicity and photosensitivity — baseline and periodic monitoring (TFTs, LFTs, CXR) is required for anyone started on long-term therapy.', 3),
('d1000000-0000-0000-0000-000000000002', 'DRESS syndrome typically develops 2-8 weeks after starting the causative drug and features fever, widespread rash, facial oedema, lymphadenopathy, eosinophilia and internal organ involvement (commonly liver, less often kidney, lung or heart).', 1),
('d1000000-0000-0000-0000-000000000002', 'Allopurinol is a well-recognised cause of DRESS and Stevens-Johnson syndrome/toxic epidermal necrolysis, particularly in patients carrying HLA-B*58:01 (more common in certain East and South Asian populations) — pre-treatment screening is recommended in high-risk groups.', 2),
('d1000000-0000-0000-0000-000000000002', 'Management is immediate and permanent withdrawal of the culprit drug, supportive care, and systemic corticosteroids for significant organ involvement; recovery can take weeks and relapse can occur as steroids are tapered.', 3),
('d1000000-0000-0000-0000-000000000003', 'Methotrexate pneumonitis is an idiosyncratic hypersensitivity reaction, not simply dose-dependent, and can occur at any time during treatment; it presents subacutely with dry cough, dyspnoea, fever and bilateral infiltrates, and must be distinguished from opportunistic infection.', 1),
('d1000000-0000-0000-0000-000000000003', 'Because clinical features overlap with infection (which methotrexate-associated immunosuppression also predisposes to), management typically involves stopping the drug, empirical antimicrobial cover, and further investigation (HRCT, bronchoalveolar lavage) rather than assuming either diagnosis alone.', 2),
('d1000000-0000-0000-0000-000000000003', 'Once methotrexate pneumonitis is suspected, the drug is usually permanently discontinued, and corticosteroids may be used for more severe cases; rechallenge is generally avoided given the risk of recurrence.', 3),
('d1000000-0000-0000-0000-000000000004', 'Macrolides (particularly clarithromycin and erythromycin, but not azithromycin) are potent CYP3A4 inhibitors and significantly increase plasma levels of statins metabolised by this pathway (simvastatin, atorvastatin), precipitating myopathy or rhabdomyolysis — this combination should be avoided or the statin temporarily withheld.', 1),
('d1000000-0000-0000-0000-000000000004', 'Rhabdomyolysis causes myoglobinuria, which gives a strongly positive urine dipstick for blood but no red cells on microscopy — an important clue distinguishing it from haematuria.', 2),
('d1000000-0000-0000-0000-000000000004', 'Management of rhabdomyolysis-associated AKI centres on early, generous intravenous fluid resuscitation to maintain urine output and prevent myoglobin cast nephropathy, alongside monitoring for hyperkalaemia.', 3),
('d1000000-0000-0000-0000-000000000005', 'Drug-induced lupus is classically associated with hydralazine, procainamide, isoniazid and minocycline, presents with arthralgia/arthritis, serositis and constitutional symptoms, and typically spares the kidneys and CNS (unlike idiopathic SLE).', 1),
('d1000000-0000-0000-0000-000000000005', 'Serologically, drug-induced lupus is characterised by strongly positive antinuclear and anti-histone antibodies, with anti-dsDNA usually negative and complement levels typically normal — helpful in distinguishing it from idiopathic SLE.', 2),
('d1000000-0000-0000-0000-000000000005', 'The mainstay of management is withdrawal of the causative drug, after which symptoms usually resolve gradually over weeks to months; NSAIDs or a short corticosteroid course may be used for symptom control while awaiting resolution.', 3),
('d1000000-0000-0000-0000-000000000006', 'Lamotrigine-associated SJS/TEN risk is strongly linked to rapid dose escalation and concurrent sodium valproate use (which inhibits lamotrigine metabolism, raising levels); slow, guideline-directed titration reduces but does not eliminate this risk.', 1),
('d1000000-0000-0000-0000-000000000006', $x$SJS/TEN involves epidermal necrolysis with mucosal involvement (oral, ocular, genital) and a positive Nikolsky's sign (epidermis shears with lateral pressure); body surface area involvement distinguishes SJS (<10%), SJS/TEN overlap (10-30%) and TEN (>30%).$x$, 2),
('d1000000-0000-0000-0000-000000000006', 'Management is immediate withdrawal of all suspected causative drugs and transfer to a specialist burns or dermatology unit for supportive, often multidisciplinary, care; the causative drug (and structurally related drugs) must be permanently avoided.', 3),
('d1000000-0000-0000-0000-000000000007', 'Clozapine carries a risk of agranulocytosis (roughly 0.8% of patients, highest in the first 18 weeks of treatment), which is why mandatory regular full blood count monitoring is a legal requirement throughout treatment via a patient monitoring service.', 1),
('d1000000-0000-0000-0000-000000000007', 'UK monitoring systems use a traffic-light system for neutrophil/white cell counts (green/amber/red); an amber or red result requires either more frequent monitoring or immediate cessation of clozapine depending on the severity of the fall.', 2),
('d1000000-0000-0000-0000-000000000007', $x$Once clozapine is stopped for neutropenia, it is normally permanently discontinued (rechallenge is only considered in exceptional circumstances under specialist supervision), and the patient's psychiatric management must be reviewed, as clozapine is often used for treatment-resistant disease.$x$, 3),
('d1000000-0000-0000-0000-000000000008', 'ACE inhibitor angioedema is bradykinin-mediated (due to reduced bradykinin breakdown), not IgE/histamine-mediated, which is why it typically lacks urticaria or itch and does not respond to antihistamines or adrenaline as reliably as anaphylaxis.', 1),
('d1000000-0000-0000-0000-000000000008', 'It can occur at any time during treatment, including after years of uneventful use, and carries a small but definite risk of life-threatening airway obstruction requiring urgent airway assessment and, in severe cases, escalation to anaesthetic/ENT support.', 2),
('d1000000-0000-0000-0000-000000000008', 'After ACE inhibitor angioedema, ARBs carry a smaller but real risk of cross-reactivity and are generally avoided or used with caution, particularly after a severe reaction; calcium channel blockers or other drug classes are preferred alternatives.', 3),
('d1000000-0000-0000-0000-000000000009', 'Andexanet alfa is a specific reversal agent for factor Xa inhibitors (apixaban, rivaroxaban) in life-threatening bleeding; four-factor PCC is a reasonable alternative when andexanet is unavailable or contraindicated (e.g. cost/availability constraints in many centres).', 1),
('d1000000-0000-0000-0000-000000000009', 'Idarucizumab specifically reverses dabigatran; protamine reverses unfractionated (and partially LMW) heparin; vitamin K and FFP/PCC reverse warfarin — matching the reversal agent to the specific anticoagulant class is essential.', 2),
('d1000000-0000-0000-0000-000000000009', 'In major DOAC-associated bleeding, reversal is combined with standard resuscitation (fluids, blood products), identification and control of the bleeding source (e.g. urgent endoscopy), and correction of any contributing coagulopathy or thrombocytopenia.', 3),
('d1000000-0000-0000-0000-000000000010', 'In patients with AF undergoing PCI, guidelines favour minimising triple therapy (aspirin + P2Y12 inhibitor + anticoagulant) duration to reduce bleeding risk, typically limiting it to the periprocedural period only, then continuing dual therapy (P2Y12 inhibitor + anticoagulant) for up to 12 months.', 1),
('d1000000-0000-0000-0000-000000000010', 'DOACs are generally preferred over warfarin in this combination-therapy setting, as trial evidence shows lower bleeding rates without a clear increase in ischaemic events, provided renal function allows appropriate dosing.', 2),
('d1000000-0000-0000-0000-000000000010', 'After the dual therapy period (usually 12 months post-ACS/PCI), antiplatelet therapy is typically stopped and the patient continues on anticoagulant monotherapy for ongoing stroke prevention in AF.', 3),
('d1000000-0000-0000-0000-000000000011', 'Management of warfarin over-anticoagulation is stratified by INR level and bleeding severity: minor over-anticoagulation without bleeding may need only dose omission, while INR >8 (with or without minor bleeding) warrants oral vitamin K, and major bleeding at any INR requires urgent PCC plus IV vitamin K.', 1),
('d1000000-0000-0000-0000-000000000011', 'DOACs are contraindicated in mechanical heart valves (shown to increase thromboembolic and bleeding events compared with warfarin in trial data), so warfarin must be continued long-term in this population despite the inconvenience of monitoring.', 2),
('d1000000-0000-0000-0000-000000000011', 'After correcting a supratherapeutic INR, warfarin is typically restarted at a reduced dose once INR falls into the therapeutic range, with closer monitoring and review of any precipitant (e.g. new interacting drug, illness, dietary change, poor adherence).', 3),
('d1000000-0000-0000-0000-000000000012', 'HIT typically occurs 5-10 days after heparin exposure (or more rapidly with recent prior exposure) and is characterised by a significant platelet count fall (usually >50%) together with new or progressive thrombosis, despite heparin anticoagulation — a paradoxical prothrombotic state.', 1),
('d1000000-0000-0000-0000-000000000012', 'All heparin products (unfractionated and low molecular weight) must be stopped immediately once HIT is clinically suspected, without waiting for laboratory confirmation, given the high risk of limb- and life-threatening thrombosis.', 2),
('d1000000-0000-0000-0000-000000000012', 'Warfarin should not be started until the platelet count has recovered substantially and should always overlap with a non-heparin parenteral anticoagulant, because early warfarin monotherapy in HIT can precipitate warfarin-induced skin necrosis or venous limb gangrene.', 3),
('d1000000-0000-0000-0000-000000000013', $x$Warfarin exposure between roughly 6 and 12 weeks' gestation carries a dose-dependent risk of warfarin embryopathy (nasal hypoplasia, skeletal abnormalities); risk is lower with warfarin doses under 5 mg/day, which influences the individualised choice between continuing warfarin or switching to heparin in the first trimester.$x$, 1),
('d1000000-0000-0000-0000-000000000013', 'Mechanical heart valves require therapeutic (not prophylactic) anticoagulation throughout pregnancy given the very high risk of valve thrombosis if under-anticoagulated; if LMWH is used, dosing must be adjusted to anti-Xa levels rather than fixed weight-based dosing alone.', 2),
('d1000000-0000-0000-0000-000000000013', $x$Warfarin is typically substituted with heparin prior to delivery because of the risk of fetal intracranial haemorrhage during birth if warfarin is still active, and because heparin's effects are more readily reversed/managed peripartum.$x$, 3),
('d1000000-0000-0000-0000-000000000014', 'For most patients with AF undergoing surgery, routine heparin bridging is not recommended unless they are at high thromboembolic risk (e.g. mechanical valve, CHA2DS2-VASc very high, recent stroke/TIA within 3 months) because bridging increases bleeding without a proven reduction in thromboembolic events (BRIDGE trial).', 1),
('d1000000-0000-0000-0000-000000000014', 'Warfarin is typically stopped approximately 5 days before surgery to allow the INR to normalise (given its long half-life and reliance on synthesis of new clotting factors), with the exact timing individualised to baseline INR and procedure urgency.', 2),
('d1000000-0000-0000-0000-000000000014', 'Restarting anticoagulation postoperatively is guided by the achieved surgical haemostasis and ongoing bleeding risk rather than a fixed protocol, balancing thromboembolic risk against postoperative bleeding risk.', 3),
('d1000000-0000-0000-0000-000000000015', 'Apixaban dose reduction to 2.5 mg twice daily is based on meeting at least two of three criteria: age >=80 years, body weight <=60 kg, or serum creatinine >=133 micromol/L — not on eGFR/creatinine clearance thresholds alone as with some other DOACs.', 1),
('d1000000-0000-0000-0000-000000000015', 'Among the DOACs, apixaban has the lowest degree of renal elimination, making it a favoured choice in patients with renal impairment; dabigatran, being predominantly renally cleared, requires more caution and is avoided at lower eGFRs.', 2),
('d1000000-0000-0000-0000-000000000015', 'DOACs are generally avoided when eGFR falls below approximately 15 mL/min/1.73m2 or in dialysis-dependent patients (with apixaban having the most evidence for cautious use in advanced CKD of the group), at which point warfarin (with its established dosing in renal failure) is often preferred.', 3),
('d1000000-0000-0000-0000-000000000016', 'In patients with high bleeding risk after ACS/PCI, guideline-supported strategies include de-escalating from a potent P2Y12 inhibitor (ticagrelor/prasugrel) to clopidogrel, or shortening dual antiplatelet therapy duration, individualised against ongoing ischaemic risk.', 1),
('d1000000-0000-0000-0000-000000000016', 'Proton pump inhibitors reduce the risk of upper gastrointestinal bleeding in patients on dual antiplatelet therapy and are recommended, particularly after a prior GI bleed or in patients with other risk factors for GI bleeding.', 2),
('d1000000-0000-0000-0000-000000000016', 'The decision to de-escalate, shorten, or stop antiplatelet therapy after a major bleed requires balancing individualised ischaemic risk (stent type, time since ACS, extent of coronary disease) against bleeding risk, rather than a one-size-fits-all approach.', 3),
('d1000000-0000-0000-0000-000000000017', 'Trimethoprim (including as co-trimoxazole) is a clinically important CYP2C9 inhibitor and significantly increases INR in patients on warfarin; alternative antibiotics should be considered where possible, or INR monitored closely if co-trimoxazole/trimethoprim must be used.', 1),
('d1000000-0000-0000-0000-000000000017', 'Metronidazole and macrolides (via CYP3A4/other pathways) are similarly recognised for potentiating warfarin; whenever a new antimicrobial is started in a patient on warfarin, the potential for interaction should prompt closer INR monitoring.', 2),
('d1000000-0000-0000-0000-000000000017', 'Management of an elevated INR is guided by both the level and the presence/severity of bleeding: INR >8 or bleeding at lower INR levels generally warrants oral vitamin K in addition to withholding warfarin.', 3),
('d1000000-0000-0000-0000-000000000018', 'Clarithromycin and erythromycin are strong CYP3A4 inhibitors and significantly increase levels of statins metabolised via this pathway (simvastatin, atorvastatin), raising the risk of myopathy and rhabdomyolysis; azithromycin has a lower interaction potential.', 1),
('d1000000-0000-0000-0000-000000000018', $x$When a significant interaction risk is identified, the statin (rather than the essential antimicrobial, where no suitable alternative exists) is usually the drug temporarily withheld, given the antibiotic course is short and the statin's cardiovascular benefit is not meaningfully reduced by a brief interruption.$x$, 2),
('d1000000-0000-0000-0000-000000000018', 'Fluvastatin, pravastatin and rosuvastatin have less CYP3A4-dependent metabolism and are sometimes used as alternatives when a statin must be continued alongside a CYP3A4 inhibitor, though caution and monitoring are still advised.', 3),
('d1000000-0000-0000-0000-000000000019', 'Linezolid has weak, reversible monoamine oxidase inhibitor activity and is a recognised precipitant of serotonin syndrome when combined with serotonergic drugs (SSRIs, SNRIs, triptans, tramadol, MAOIs); this combination should generally be avoided.', 1),
('d1000000-0000-0000-0000-000000000019', 'Serotonin syndrome is characterised by the triad of autonomic instability (hyperthermia, diaphoresis, tachycardia), neuromuscular abnormalities (hyperreflexia, clonus, tremor) and altered mental state (agitation, confusion) developing rapidly after a precipitant.', 2),
('d1000000-0000-0000-0000-000000000019', 'Management is supportive: stopping all serotonergic agents, benzodiazepines for agitation/rigidity, active cooling for hyperthermia, and cyproheptadine (a serotonin antagonist) for moderate-to-severe cases unresponsive to initial measures.', 3),
('d1000000-0000-0000-0000-000000000020', 'Trimethoprim-sulfamethoxazole should be avoided in patients on methotrexate because both drugs impair folate metabolism (synergistic antifolate effect) and co-trimoxazole also reduces renal tubular secretion of methotrexate, together substantially raising the risk of severe, potentially fatal pancytopenia and mucositis.', 1),
('d1000000-0000-0000-0000-000000000020', 'Methotrexate toxicity from drug interactions or accidental overdosing (e.g. daily instead of weekly dosing) is treated with folinic acid (calcium folinate) rescue, which bypasses the block in folate metabolism, alongside supportive care and treatment of any resulting cytopenias/sepsis.', 2),
('d1000000-0000-0000-0000-000000000020', 'This interaction underscores the importance of medication reconciliation before prescribing antibiotics for patients on methotrexate or other antifolate/immunosuppressive drugs, particularly in out-of-hours or unfamiliar clinical settings.', 3),
('d1000000-0000-0000-0000-000000000021', $x$The 'triple whammy' interaction (ACE inhibitor/ARB + diuretic + NSAID) is a well-recognised cause of acute kidney injury, particularly in patients with pre-existing renal impairment, heart failure or volume depletion; NSAIDs should be avoided or used with extreme caution in this population.$x$, 1),
('d1000000-0000-0000-0000-000000000021', 'ACE inhibitors reduce aldosterone-mediated potassium excretion and spironolactone directly blocks the mineralocorticoid receptor; combined, they carry a recognised hyperkalaemia risk requiring regular monitoring, which is compounded further by any superimposed renal impairment.', 2),
('d1000000-0000-0000-0000-000000000021', 'Patients on ACE inhibitors/ARBs and/or potassium-sparing diuretics should be counselled to avoid over-the-counter NSAIDs and to seek medical advice before starting one, given the risk of this dangerous interaction.', 3),
('d1000000-0000-0000-0000-000000000022', 'Azole antifungals (fluconazole, and more potently itraconazole and voriconazole) inhibit CYP2C9 and CYP2C19, significantly raising levels of drugs metabolised by these pathways, including phenytoin and warfarin.', 1),
('d1000000-0000-0000-0000-000000000022', 'Phenytoin exhibits zero-order (non-linear, saturable) kinetics at higher, therapeutic-to-toxic concentrations, meaning small dose or clearance changes can produce disproportionately large changes in plasma level — levels should be monitored closely whenever an interacting drug is started or stopped.', 2),
('d1000000-0000-0000-0000-000000000022', 'Classic features of phenytoin toxicity follow a dose-related sequence: nystagmus first, then ataxia and dysarthria, then at higher levels lethargy, confusion and (at very high levels) paradoxical seizures.', 3),
('d1000000-0000-0000-0000-000000000023', 'Amiodarone inhibits P-glycoprotein and reduces both renal and biliary clearance of digoxin, typically raising digoxin levels by around 70-100%; a pre-emptive digoxin dose reduction is usually recommended when amiodarone is co-prescribed, with level monitoring.', 1),
('d1000000-0000-0000-0000-000000000023', 'Digoxin toxicity classically presents with gastrointestinal symptoms (nausea, vomiting, anorexia), visual disturbance (blurred or yellow-green tinged vision, halos), confusion, and a wide range of arrhythmias including ventricular ectopy, bigeminy and heart block.', 2),
('d1000000-0000-0000-0000-000000000023', 'Intravenous calcium is contraindicated in digoxin toxicity due to the risk of exacerbating cardiac toxicity; digoxin-specific antibody fragments are the definitive treatment for significant toxicity, particularly with haemodynamic compromise, severe arrhythmia, or hyperkalaemia from acute massive overdose.', 3),
('d1000000-0000-0000-0000-000000000024', $x$Clopidogrel requires hepatic activation via CYP2C19 to its active metabolite; omeprazole and esomeprazole are relatively potent CYP2C19 inhibitors and may reduce clopidogrel's antiplatelet effect, whereas pantoprazole has minimal CYP2C19 inhibitory activity and is generally preferred when a PPI is needed alongside clopidogrel.$x$, 1),
('d1000000-0000-0000-0000-000000000024', 'This interaction is not relevant to prasugrel or ticagrelor, which do not depend on CYP2C19 activation in the same way, so PPI choice is less of a concern if a patient is on one of these agents instead of clopidogrel.', 2),
('d1000000-0000-0000-0000-000000000024', 'Gastroprotection with a PPI remains appropriate (and often recommended) in patients on dual antiplatelet therapy with risk factors for GI bleeding; the clinical response to a theoretical interaction is careful drug selection, not withholding indicated therapy.', 3),
('d1000000-0000-0000-0000-000000000025', 'Loading dose = target plasma concentration x volume of distribution (Vd); it is independent of clearance and is used to rapidly achieve therapeutic concentrations for drugs with a long half-life where waiting for steady state via maintenance dosing would be too slow.', 1),
('d1000000-0000-0000-0000-000000000025', 'Maintenance dose is governed by clearance (maintenance dose rate = clearance x target concentration) and determines the steady-state concentration achieved with ongoing regular dosing.', 2),
('d1000000-0000-0000-0000-000000000025', 'Time to steady state depends only on half-life (approximately 4-5 half-lives), not on dose size or dosing interval — this is why a loading dose, not a higher maintenance dose, is used to shorten the time to therapeutic effect.', 3),
('d1000000-0000-0000-0000-000000000026', 'Phenytoin transitions from first-order to zero-order (saturable, Michaelis-Menten) kinetics as hepatic metabolising capacity becomes saturated near therapeutic concentrations, meaning dose increases in this range should be small and levels checked before further titration.', 1),
('d1000000-0000-0000-0000-000000000026', 'Because of this non-linearity, phenytoin dosing is typically adjusted in small increments (e.g. 25-50 mg) with level monitoring once near the therapeutic range, rather than the larger proportional adjustments that would be reasonable for a drug with simple first-order kinetics.', 2),
('d1000000-0000-0000-0000-000000000026', 'Other drugs exhibiting zero-order kinetics at therapeutic/toxic concentrations include ethanol and, at high doses, aspirin/salicylate — recognising this pattern is important for anticipating disproportionate toxicity risk with dose escalation.', 3),
('d1000000-0000-0000-0000-000000000027', 'For high hepatic-extraction-ratio drugs (e.g. lidocaine, propranolol, morphine, verapamil), clearance is flow-limited — it depends primarily on hepatic blood flow, so conditions reducing hepatic perfusion (cirrhosis with portosystemic shunting, heart failure, shock) markedly reduce clearance and increase systemic exposure, especially after IV administration or with repeated oral dosing (also raising oral bioavailability by reducing first-pass extraction).', 1),
('d1000000-0000-0000-0000-000000000027', 'For low hepatic-extraction-ratio drugs (e.g. phenytoin, warfarin, theophylline), clearance is capacity-limited and depends more on intrinsic enzyme activity and the unbound (free) drug fraction, making protein binding and enzyme induction/inhibition more clinically relevant than blood flow changes.', 2),
('d1000000-0000-0000-0000-000000000027', 'In cirrhosis, both portosystemic shunting (reducing effective first-pass extraction and increasing oral bioavailability of high-extraction drugs) and reduced hepatocyte mass/enzyme activity contribute to altered drug handling, requiring empirical dose reduction and close monitoring for many drugs.', 3),
('d1000000-0000-0000-0000-000000000028', $x$Time to steady state is determined solely by a drug's half-life (approximately 4-5 half-lives to reach ~94-97% of steady state), independent of dose size, dosing interval, or route of administration.$x$, 1),
('d1000000-0000-0000-0000-000000000028', $x$Amiodarone's very long and variable half-life (weeks to months) due to extensive tissue (particularly adipose) accumulation is why it requires a loading regimen for timely therapeutic effect, and also why its adverse effects and drug interactions can persist for a prolonged period after the drug is stopped.$x$, 2),
('d1000000-0000-0000-0000-000000000028', 'This principle applies broadly: any drug with a long half-life (e.g. amiodarone, digoxin to a lesser extent) needs a loading strategy if rapid therapeutic effect is required, since maintenance dosing alone would take a clinically impractical time to reach steady state.', 3),
('d1000000-0000-0000-0000-000000000029', 'Highly protein-bound drugs (warfarin, phenytoin) are susceptible to clinically significant displacement interactions, particularly in patients with hypoalbuminaemia, where a smaller absolute change in bound drug produces a larger relative change in free (active) drug concentration.', 1),
('d1000000-0000-0000-0000-000000000029', $x$Total plasma drug concentration (as usually measured/reported) can remain within the 'normal' range while free drug concentration — and hence pharmacological effect — rises substantially; this is an important pitfall when interpreting drug levels in hypoalbuminaemic patients.$x$, 2),
('d1000000-0000-0000-0000-000000000029', 'NSAIDs like ibuprofen compound bleeding risk in patients on warfarin through multiple mechanisms: protein binding displacement, antiplatelet effects, and gastric mucosal irritation — the combination should generally be avoided or used with very close monitoring.', 3),
('d1000000-0000-0000-0000-000000000030', 'Bioavailability describes the fraction of an administered dose that reaches the systemic circulation unchanged; drugs with extensive hepatic first-pass metabolism (propranolol, morphine, lidocaine, GTN) have low oral bioavailability, requiring much larger oral doses than parenteral doses to achieve equivalent systemic exposure.', 1),
('d1000000-0000-0000-0000-000000000030', 'Intravenous administration has, by definition, 100% bioavailability, as it bypasses gastrointestinal absorption and hepatic first-pass metabolism entirely — this is the key reason IV-to-oral (or oral-to-IV) dose conversions are often not 1:1 for high first-pass drugs.', 2),
('d1000000-0000-0000-0000-000000000030', 'Awareness of first-pass metabolism is clinically important when switching routes of administration (e.g. in acutely unwell patients unable to take oral medication), to avoid significant under- or over-dosing if an inappropriate conversion ratio is used.', 3),
('d1000000-0000-0000-0000-000000000031', 'CYP2D6 exhibits significant genetic polymorphism, with poor, intermediate, extensive (normal) and ultra-rapid metaboliser phenotypes; ultra-rapid metabolisers convert codeine to morphine unusually quickly and extensively, risking opioid toxicity even at standard codeine doses.', 1),
('d1000000-0000-0000-0000-000000000031', 'Because of documented neonatal deaths from this mechanism, regulatory guidance now advises caution or avoidance of codeine in breastfeeding mothers (and codeine is also contraindicated in children under 12 and in those with respiratory or other risk factors, and in ultra-rapid metabolisers of any age).', 2),
('d1000000-0000-0000-0000-000000000031', 'Tramadol shares a similar CYP2D6-dependent activation pathway to an active metabolite and carries analogous pharmacogenomic concerns, whereas morphine itself (not requiring CYP2D6 activation) does not carry this specific risk.', 3),
('d1000000-0000-0000-0000-000000000032', 'Aminoglycosides (gentamicin) exhibit concentration-dependent bactericidal killing, so an adequate peak concentration is important for efficacy, while trough levels reflect clearance and relate to toxicity risk (nephrotoxicity, ototoxicity) — this is why once-daily extended-interval dosing regimens are commonly used.', 1),
('d1000000-0000-0000-0000-000000000032', 'In renal impairment, aminoglycoside clearance is reduced, leading to drug accumulation if the dosing interval is not appropriately extended; the standard adjustment is to lengthen the interval (guided by levels) rather than to reduce the individual dose, preserving peak efficacy while avoiding trough accumulation.', 2),
('d1000000-0000-0000-0000-000000000032', 'Therapeutic drug monitoring (peak and trough levels) is essential for aminoglycosides given their narrow therapeutic index and reflects both pharmacokinetic principles (clearance, accumulation) and their concentration-dependent efficacy/toxicity relationship.', 3),
('d1000000-0000-0000-0000-000000000033', 'The paracetamol treatment nomogram applies only to a single, acute overdose with a reliably known ingestion time; it should never be used to guide treatment decisions in staggered, repeated, or uncertain-timing overdoses.', 1),
('d1000000-0000-0000-0000-000000000033', 'In staggered overdose, treatment thresholds are based on total dose ingested (e.g. >75-150 mg/kg over 24 hours depending on risk factors) and any evidence of current or evolving hepatotoxicity, with a low threshold to treat given the difficulty in excluding significant risk.', 2),
('d1000000-0000-0000-0000-000000000033', 'Rising transaminases and even mild coagulopathy in the context of any paracetamol overdose (staggered or acute) indicate hepatotoxicity is already underway and mandate N-acetylcysteine treatment regardless of the current paracetamol level.', 3),
('d1000000-0000-0000-0000-000000000034', 'Salicylate poisoning classically causes a mixed acid-base picture: an early respiratory alkalosis (direct respiratory centre stimulation) followed by a metabolic acidosis, and severe poisoning often shows a combined picture as seen here (low pH with low pCO2 and low bicarbonate).', 1),
('d1000000-0000-0000-0000-000000000034', 'Haemodialysis indications in salicylate poisoning include: very high salicylate levels, altered mental status/coma, severe/refractory metabolic acidosis, pulmonary oedema, renal failure, and clinical deterioration despite supportive treatment.', 2),
('d1000000-0000-0000-0000-000000000034', $x$Intubation and mechanical ventilation should be avoided where possible in salicylate poisoning because it is difficult to replicate the patient's own compensatory hyperventilation, and inadequate ventilation can precipitate rapid, severe acidosis and clinical deterioration.$x$, 3),
('d1000000-0000-0000-0000-000000000035', 'Tricyclic antidepressant toxicity results primarily from fast sodium channel blockade in cardiac myocytes, causing QRS widening, arrhythmias and hypotension, plus anticholinergic effects (tachycardia, dry mouth, urinary retention, confusion) and alpha-blockade contributing to hypotension.', 1),
('d1000000-0000-0000-0000-000000000035', 'A QRS duration >100 ms predicts seizure risk, and >160 ms predicts ventricular arrhythmia risk in TCA overdose; a terminal R wave in aVR >3mm is another recognised marker of significant TCA toxicity.', 2),
('d1000000-0000-0000-0000-000000000035', 'Sodium bicarbonate is given for QRS widening, arrhythmia, or hypotension in TCA overdose, targeting a plasma pH of around 7.50-7.55; class Ia/Ic antiarrhythmics are contraindicated as they compound sodium channel blockade.', 3),
('d1000000-0000-0000-0000-000000000036', 'Chronic lithium toxicity (often precipitated by dehydration, renal impairment, or interacting drugs such as NSAIDs, ACE inhibitors/ARBs, or diuretics reducing lithium clearance) tends to cause more severe neurotoxicity at lower levels than acute overdose, because tissue (including CNS) lithium concentrations are already elevated.', 1),
('d1000000-0000-0000-0000-000000000036', 'Haemodialysis indications in lithium toxicity include: severe neurological symptoms (seizures, coma, significant confusion), very high levels (particularly with renal impairment), renal failure preventing adequate clearance, or inability to tolerate/absorb oral fluids/lithium cessation measures.', 2),
('d1000000-0000-0000-0000-000000000036', 'Activated charcoal, urinary alkalinisation and loop diuretics have no proven role in enhancing lithium elimination; supportive care with isotonic saline to restore euvolaemia (avoiding diuretics) and dialysis for severe cases are the mainstays of management.', 3),
('d1000000-0000-0000-0000-000000000037', 'Bidirectional ventricular tachycardia is a rhythm strongly and specifically associated with digoxin toxicity, alongside other arrhythmias including various degrees of AV block, ventricular ectopy/bigeminy, and atrial tachycardia with block.', 1),
('d1000000-0000-0000-0000-000000000037', $x$Hyperkalaemia in acute or acute-on-chronic digoxin toxicity results from inhibition of the Na+/K+-ATPase pump and correlates with severity/mortality; it should prompt urgent DigiFab administration rather than standard hyperkalaemia management alone, given intravenous calcium's relative contraindication.$x$, 2),
('d1000000-0000-0000-0000-000000000037', 'DigiFab is indicated for life-threatening arrhythmias, severe hyperkalaemia attributable to digoxin toxicity, or very high digoxin levels (particularly with renal impairment reducing clearance), and rapidly neutralises free digoxin, reversing toxicity.', 3),
('d1000000-0000-0000-0000-000000000038', 'Glucagon is the specific antidote for symptomatic beta-blocker overdose, activating myocardial adenylate cyclase independent of the beta-adrenergic receptor and thereby increasing heart rate and contractility despite ongoing beta-blockade.', 1),
('d1000000-0000-0000-0000-000000000038', 'Atropine often has limited efficacy in beta-blocker-induced bradycardia because the mechanism is direct beta-receptor blockade rather than predominantly vagally mediated bradycardia.', 2),
('d1000000-0000-0000-0000-000000000038', 'High-dose insulin-euglycaemia therapy is an important second-line/adjunctive treatment for refractory beta-blocker (and calcium channel blocker) cardiotoxicity, improving myocardial contractility via metabolic/inotropic mechanisms; calcium gluconate is more specifically used in calcium channel blocker overdose.', 3),
('d1000000-0000-0000-0000-000000000039', 'High-dose insulin-euglycaemia therapy (HIET) is the treatment of choice for cardiogenic shock in calcium channel blocker overdose refractory to fluids and calcium, improving myocardial contractility and providing some vasodilatory benefit, and requires concurrent dextrose and potassium monitoring.', 1),
('d1000000-0000-0000-0000-000000000039', 'Calcium salts (calcium gluconate or calcium chloride) provide a useful initial and often transient improvement in CCB overdose by increasing extracellular calcium to partially overcome channel blockade, but their effect frequently wanes, necessitating escalation to HIET or other measures.', 2),
('d1000000-0000-0000-0000-000000000039', 'Dihydropyridine calcium channel blockers (e.g. amlodipine) in overdose predominantly cause profound vasodilation with relatively preserved or reflex-elevated heart rate, whereas non-dihydropyridines (verapamil, diltiazem) more prominently cause bradycardia and negative inotropy/dromotropy — both can cause severe, refractory shock in overdose.', 3),
('d1000000-0000-0000-0000-000000000040', $x$Naloxone's duration of action (roughly 30-90 minutes) is typically shorter than that of the opioid causing overdose, creating a risk of renarcotisation (return of respiratory depression) as naloxone wears off while the opioid remains active — a key reason for mandatory observation after reversal.$x$, 1),
('d1000000-0000-0000-0000-000000000040', 'The required observation period depends on the opioid involved (longer for long-acting or extended-release opioids, methadone, or large ingested doses) and clinical response; patients should not be discharged immediately after apparent full recovery from a single naloxone dose.', 2),
('d1000000-0000-0000-0000-000000000040', 'In cases of ongoing or recurrent toxicity, a naloxone infusion (rather than repeated bolus dosing alone) may be used to maintain reversal over a more sustained period while the causative opioid is cleared.', 3),
('d1000000-0000-0000-0000-000000000041', 'Ethylene glycol and methanol are both metabolised by alcohol dehydrogenase to toxic metabolites causing severe anion gap metabolic acidosis and organ-specific toxicity (renal injury with calcium oxalate crystalluria for ethylene glycol; ocular/optic nerve toxicity for methanol).', 1),
('d1000000-0000-0000-0000-000000000041', 'Fomepizole (or, as an alternative, ethanol) competitively inhibits alcohol dehydrogenase, preventing toxic metabolite formation, and is most effective when given early before extensive metabolism has occurred; both a raised osmolar gap (early, from unmetabolised parent compound) and a raised anion gap (later, from toxic metabolites) can be seen depending on the time since ingestion.', 2),
('d1000000-0000-0000-0000-000000000041', 'Haemodialysis is used in severe ethylene glycol or methanol poisoning (significant acidosis, visual symptoms, renal impairment, or very high levels) as it removes both the parent alcohol and its toxic metabolites, and is often combined with ongoing fomepizole/ethanol therapy.', 3),
('d1000000-0000-0000-0000-000000000042', $x$The 'triple whammy' combination of an ACE inhibitor/ARB, a diuretic, and an NSAID is a well-recognised and common cause of drug-induced acute kidney injury, particularly in elderly patients, those with pre-existing renal impairment, or during intercurrent volume depletion (e.g. illness, reduced oral intake).$x$, 1),
('d1000000-0000-0000-0000-000000000042', 'NSAIDs reduce renal prostaglandin synthesis, impairing the compensatory afferent arteriolar vasodilation that maintains glomerular perfusion when renal blood flow is compromised, particularly relevant in patients already reliant on this mechanism (heart failure, CKD, volume depletion, or ACE inhibitor/ARB therapy affecting efferent tone).', 2),
('d1000000-0000-0000-0000-000000000042', $x$Patients on ACE inhibitors/ARBs and diuretics should be counselled to avoid over-the-counter NSAIDs and to seek medical advice during acute illness (a 'sick day rules' approach — temporarily stopping ACE inhibitors/ARBs, diuretics and NSAIDs/metformin during acute dehydrating illness) to reduce AKI risk.$x$, 3),
('d1000000-0000-0000-0000-000000000043', 'Metformin dose review typically occurs at eGFR <45 mL/min/1.73m2 (consider dose reduction) and metformin is generally stopped at eGFR <30 mL/min/1.73m2, due to accumulation risk and increased likelihood of lactic acidosis, a rare but serious and potentially fatal complication.', 1),
('d1000000-0000-0000-0000-000000000043', 'A significant, unexplained fall in eGFR (as seen here, from 55 to 24) warrants its own clinical evaluation for an underlying cause, separate from the medication adjustment required, particularly to identify reversible contributors.', 2),
('d1000000-0000-0000-0000-000000000043', 'When metformin is stopped or reduced in CKD, alternative glucose-lowering therapies must be considered with their own renal dosing/safety profiles in mind (e.g. certain SGLT2 inhibitors and DPP-4 inhibitors have specific eGFR thresholds and cautions, while sulfonylureas carry increased hypoglycaemia risk in renal impairment).', 3),
('d1000000-0000-0000-0000-000000000044', $x$Morphine's active metabolites (morphine-6-glucuronide, a potent analgesic/respiratory depressant, and morphine-3-glucuronide, associated with neuroexcitatory effects) are renally excreted and accumulate in renal impairment, increasing the risk of toxicity even at previously tolerated doses.$x$, 1),
('d1000000-0000-0000-0000-000000000044', 'Fentanyl and alfentanil are largely hepatically metabolised to inactive metabolites, making them relatively favourable choices in significant renal impairment; oxycodone is an alternative but still requires caution and dose reduction as some metabolite accumulation can occur.', 2),
('d1000000-0000-0000-0000-000000000044', 'Codeine and dihydrocodeine share similar concerns to morphine (partly via conversion to morphine) and are generally avoided or used with great caution in significant renal impairment, particularly at higher, regular doses.', 3),
('d1000000-0000-0000-0000-000000000045', 'Low molecular weight heparins are predominantly renally cleared and accumulate in significant renal impairment (creatinine clearance <30 mL/min), increasing bleeding risk; dose adjustment with anti-Xa monitoring, or use of unfractionated heparin instead, is recommended in this setting.', 1),
('d1000000-0000-0000-0000-000000000045', 'Unfractionated heparin is not significantly renally cleared and has a shorter half-life that is more easily reversed (protamine) or discontinued, making it a preferred option when renal function is significantly impaired or unstable, or when rapid reversal capability may be needed.', 2),
('d1000000-0000-0000-0000-000000000045', 'DOACs used for VTE treatment also require caution or dose adjustment/avoidance at lower levels of renal function (thresholds vary by specific agent), so switching to a DOAC does not automatically resolve renal dosing concerns in significant CKD.', 3),
('d1000000-0000-0000-0000-000000000046', 'NSAIDs are relatively contraindicated in decompensated cirrhosis due to increased gastrointestinal bleeding risk (varices, coagulopathy, thrombocytopenia) and the risk of precipitating renal impairment or hepatorenal syndrome via reduced renal prostaglandin-mediated perfusion.', 1),
('d1000000-0000-0000-0000-000000000046', 'Paracetamol remains a reasonable first-line analgesic in cirrhosis but is often used at a reduced total daily dose as a precaution, particularly in malnourished patients or those with ongoing alcohol use, due to reduced hepatic glutathione reserves.', 2),
('d1000000-0000-0000-0000-000000000046', 'Opioids require cautious, reduced dosing and extended intervals in significant hepatic impairment due to prolonged clearance, with particular vigilance for precipitating or worsening hepatic encephalopathy, oversedation, and constipation (which itself can worsen encephalopathy).', 3),
('d1000000-0000-0000-0000-000000000047', 'Vancomycin is predominantly renally cleared and requires dose and/or interval adjustment in renal impairment, guided by therapeutic drug monitoring (trough levels or increasingly area-under-the-curve-based dosing) to maintain efficacy while minimising nephrotoxicity and ototoxicity risk.', 1),
('d1000000-0000-0000-0000-000000000047', 'Early signs of vancomycin toxicity include tinnitus and hearing changes (ototoxicity, which can become irreversible if unaddressed) and rising creatinine (nephrotoxicity); both should prompt urgent review of the dosing regimen and levels.', 2),
('d1000000-0000-0000-0000-000000000047', 'Oral vancomycin is used only for local gastrointestinal effect (e.g. C. difficile infection) due to negligible systemic absorption, and cannot be used to treat systemic infections such as bacteraemia, which require the intravenous formulation.', 3),
('d1000000-0000-0000-0000-000000000048', 'Statins are contraindicated in active liver disease, including unexplained persistently elevated transaminases (commonly cited as more than 3x the upper limit of normal) and decompensated cirrhosis, due to hepatotoxicity risk and difficulty attributing further liver injury to the drug versus the underlying disease.', 1),
('d1000000-0000-0000-0000-000000000048', 'In patients with stable, compensated liver disease and only mild, non-progressive transaminase elevation, statins may still be used with appropriate baseline and follow-up liver function monitoring, as cardiovascular risk reduction often still outweighs the small hepatotoxicity risk in this group.', 2),
('d1000000-0000-0000-0000-000000000048', 'Decisions about resuming lipid-lowering therapy in a patient who has had cirrhosis-related statin cessation should involve hepatology input and reassessment of liver disease severity/stability, alongside consideration of alternative lipid-lowering strategies if appropriate.', 3),
('d1000000-0000-0000-0000-000000000049', $x$The kidney contributes significantly to insulin clearance and degradation; as renal function declines, insulin's effective half-life and duration of action increase, raising hypoglycaemia risk even without dose changes — proactive dose reduction and increased monitoring are needed as CKD progresses.$x$, 1),
('d1000000-0000-0000-0000-000000000049', 'This effect becomes clinically more significant as eGFR falls below approximately 45-50 mL/min/1.73m2, with further caution needed at more advanced stages of CKD, and is an important cause of otherwise unexplained hypoglycaemia in patients with progressive renal impairment.', 2),
('d1000000-0000-0000-0000-000000000049', 'Other glucose-lowering drugs also require renal-specific consideration in CKD (e.g. metformin dose review/cessation, sulfonylurea hypoglycaemia risk, SGLT2 inhibitor eGFR thresholds), making regular medication review an important part of diabetes management as renal function changes.', 3),
('d1000000-0000-0000-0000-000000000050', 'Dabigatran is approximately 80% renally excreted, the highest proportion among the DOACs, making it the most affected by declining renal function and generally avoided when eGFR/creatinine clearance falls below approximately 30 mL/min/1.73m2.', 1),
('d1000000-0000-0000-0000-000000000050', 'Apixaban has the lowest renal elimination fraction of the DOACs and has the most evidence supporting (dose-adjusted) use in more advanced renal impairment, making it often the preferred DOAC choice as renal function declines, though all DOACs require individual eGFR-based review.', 2),
('d1000000-0000-0000-0000-000000000050', 'Renal function should be reassessed periodically in all patients on DOACs, particularly in older patients or those with evolving CKD, as declining renal function can shift a previously appropriate anticoagulant choice or dose into an unsafe range over time.', 3);
